# ─── Async contemplate job store ───
_CONTEMPLATE_JOBS = {}
_JOB_LOCK = threading.Lock()
_JOB_TTL_S = 600          # 2026-09-09: jobs were never evicted; RA bridge spawns ~3/min
_JOB_MAX = 256            # -> unbounded dict held full results = multi-GB RSS/commit leak
_CONT_MIN_INTERVAL_S = 15  # 2026-09-09: non-fast contemplate flood guard (see do_POST)
_LAST_NONFAST_CONTEMPLATE = 0.0
_ASYNC_JOB_IDS = set()


def _async_jobs_running():
    with _JOB_LOCK:
        return bool(_ASYNC_JOB_IDS)


def _bg_run_contemplate(job_id, query, depth, _act_meta, fast=False, skip_p5=False):
    with _JOB_LOCK:
        _ASYNC_JOB_IDS.add(job_id)
    try:
        return _bg_run_contemplate_impl(job_id, query, depth, _act_meta, fast, skip_p5)
    finally:
        with _JOB_LOCK:
            _ASYNC_JOB_IDS.discard(job_id)

def _job_store_dir():
    """The file-based result store `/contemplate-job` already reads from
    (2026-09-30: 404 on 190/287 polls — the reader existed, the writer never did)."""
    d = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', '.lae', 'jobs')
    os.makedirs(d, exist_ok=True)
    return d


def _job_persist(jid, payload):
    """Mirror a finished job to disk so a slow poller still gets it after eviction.
    Best-effort: never raise into the job thread."""
    try:
        import json as _json
        d = _job_store_dir()
        p = os.path.join(d, f'{jid}.json')
        tmp = f'{p}.tmp'
        with open(tmp, 'w', encoding='utf-8') as fh:
            _json.dump(payload, fh, ensure_ascii=False, default=str)
        os.replace(tmp, p)
        # ponytail: prune by mtime on every write (O(n) scan of a small dir);
        # a background sweeper only matters past ~10k jobs/day.
        cutoff = time.time() - 3600
        for f in os.listdir(d):
            if f.endswith('.json'):
                fp = os.path.join(d, f)
                try:
                    if os.path.getmtime(fp) < cutoff:
                        os.remove(fp)
                except OSError:
                    pass
    except Exception:
        pass


def _job_evict():
    """Evict finished jobs past TTL, then hard-cap by oldest. Caller holds _JOB_LOCK."""
    now = time.time()
    for jid in [j for j, v in _CONTEMPLATE_JOBS.items()
                if v.get("status") in ("done", "error") and now - v.get("created", now) > _JOB_TTL_S]:
        _job_persist(jid, _CONTEMPLATE_JOBS[jid])
        del _CONTEMPLATE_JOBS[jid]
    while len(_CONTEMPLATE_JOBS) > _JOB_MAX:
        oldest = min(_CONTEMPLATE_JOBS, key=lambda j: _CONTEMPLATE_JOBS[j].get("created", 0))
        _job_persist(oldest, _CONTEMPLATE_JOBS[oldest])
        del _CONTEMPLATE_JOBS[oldest]

def _p5_decision_attractor_type(resp_text):
    """Dominant type for a decision-prompt P5 job (no neural attractor ran).

    2026-10-02 credit-loop: decision jobs still act in the world, so their
    teacher samples carry the decided action's type instead of 'unknown'
    (which the training gate rejects)."""
    try:
        obj = json.loads(str(resp_text or ""))
    except Exception:
        return "action"
    if not isinstance(obj, dict):
        return "action"
    tool = str(obj.get("tool") or "")
    if tool in {"scan_blocks", "scan_nearby_entities", "look_around",
                "get_self_status", "get_world_info", "inspect_block",
                "inspect_gui", "mc_world_state", "check_status"}:
        return "sensory"
    if tool == "recall_memory":
        return "memory"
    return "action"


def _run_with_timeout(fn, timeout_s, label="p5"):
    """2026-11-03: 给 P5 的 LLM 预步加硬上限。

    实测: job fa18f95f004f 卡在 try_llm_tool_call 30 分钟以上不返回 —— 日志里只有
    [job-start], 没有 [p5-tool-call] 也没有 [job-done]; 与此同时 tick 正常推进,
    所以不是 ego 死了, 是这条预步没有边界 (llm_post_json 的 120s timeout 会叠加
    429 重试, provider 一抖动就把整个 job 拖死, 用户看到的只是"ego 不回话")。
    超时等价于"预步没拿到结果", 走原有 fallback 进 full_pipeline。

    ponytail: 超时的线程杀不掉, 会自己跑完再被丢弃; 若这条日志频繁出现, 说明该修
    provider 侧/重试策略, 而不是继续加大这个 timeout。
    """
    import concurrent.futures as _cf
    ex = _cf.ThreadPoolExecutor(max_workers=1, thread_name_prefix=f"_{label}")
    try:
        return ex.submit(fn).result(timeout=timeout_s)
    except _cf.TimeoutError:
        print(f"[{label}] timeout after {timeout_s}s -> fallback to full_pipeline", flush=True)
        return None
    except Exception as _e:
        print(f"[{label}] error {type(_e).__name__}: {_e}", flush=True)
        return None
    finally:
        ex.shutdown(wait=False)


def _p5_short_circuits(p5):
    """True only when P5 did something the neural pipeline cannot redo.

    2026-11-08: a text-only P5 answer used to replace the whole pipeline, so
    step3 (external S2 classify) never ran -> no teacher row. Measured: 0 rows
    for 5.5h while 9 of 11 contemplates routed "text". An executed tool call or
    a world decision is worth bypassing full_pipeline for; a paragraph is not.
    """
    if not isinstance(p5, dict):
        return False
    return bool(p5.get("tool_executions") or p5.get("decision_prompt"))


def _bg_run_contemplate_impl(job_id, query, depth, _act_meta, fast=False, skip_p5=False):
    """Standalone function for async contemplate execution. Runs in daemon thread."""
    print(f"[job-start] {job_id} thread={threading.current_thread().name} fast={fast} skip_p5={skip_p5}", flush=True)
    # 2026-11-12 19:10: L5 autonomous tasks reach this thread through the SAME
    # async path as external /contemplate calls. Measured: four L5 jobs
    # (integrator_synthesize / need_also / knowledge_upgrade) landed between
    # tick 71810 and 71814 while cab_type_dominance_cap_1794481760 was
    # collecting matched pairs, and ticks 71812/71813 took 129.5s / 212.0s.
    # The tick%20 metacontemplate defer does not cover this path - L5 can fire
    # on ANY tick. While a randomized trial is armed, HOLD this thread instead
    # of competing for the cores the trial is measuring: the caller already has
    # a job_id and polls for the result, so a delayed start is
    # protocol-compatible. Bounded wait: a trial must never be able to deadlock
    # the cognition pipeline (and a restart releases the flag on its first tick).
    _hold_s = 0.0
    while (bool(RESTING_STATE.get("self_experiment_armed")) and _hold_s < 900.0):
        time.sleep(5.0)
        _hold_s += 5.0
    if _hold_s:
        print(f"[contemplate-guard] job {job_id} held {_hold_s:.0f}s "
              "(randomized trial armed) - starting now", flush=True)
    _tt0 = time.time()
    try:
        # 2026-09-11 (latency): 调用方(MC 桥)要的是"动作 JSON", 不是 ego 内部工具路由。
        # 实测 p5 预步(pre-step)占一次决策的大头, 而桥早已在 POST 里带 skip_p5=true。
        # 现在真的尊重它: 直接抛进已有的 fallback 分支 → full_pipeline。
        if skip_p5:
            print("[p5-tool-call] pre-step explicitly skipped; entering full_pipeline", flush=True)
        # P5: LLM-driven tool calling pre-step — let stepfun decide if a tool
        # is needed BEFORE the expensive neural full_pipeline. If the LLM
        # returns valid tool_calls, we execute them via ToolRouter and skip
        # the neural pipeline entirely (tools ARE the answer). Any failure or
        # text-only answer returns None → normal full_pipeline (P2 regex still
        # runs inside as a second fallback). Never breaks the pipeline.
        result = None
        try:
            # 2026-09-01 NeuralDirect: verified-correction queries are answered
            # by the substrate BEFORE the rented LLM ever sees the question.
            try:
                from neural_direct import neural_direct_gate
                _nd = neural_direct_gate(query)
                if _nd.get("fired"):
                    result = {
                        "query": query,
                        "response": _nd.get("answer", ""),
                        "tool_executions": [],
                        "llm_route": "neural_direct",
                        "verdict": "neural_direct",
                        "confidence": _nd.get("sim", 0.0),
                        "margin": 1.0,
                        "temporal_bias": "none",
                        "neural_direct": {k: v for k, v in _nd.items() if k != "answer"},
                        "act": _act_meta,
                    }
                    print(f"[neural-direct] FIRED row={_nd.get('row_id')} sim={_nd.get('sim')} "
                          f"took={_nd.get('took_ms')}ms (pre-step gate)", flush=True)
            except Exception as _nde:
                print(f"[neural-direct] gate error (fallback to LLM): {_nde}", flush=True)
            if result is None:
                from stepfun_tool_caller import try_llm_tool_call
                _p5 = None if skip_p5 else _run_with_timeout(
                    lambda: try_llm_tool_call(query, decision_id=job_id),
                    float(os.environ.get("EGO_P5_TIMEOUT_S", "120") or 120),
                    label="p5-tool-call")
            else:
                _p5 = None
            if _p5 is not None and not _p5_short_circuits(_p5):
                # 2026-11-08: text-only P5 answer -> let full_pipeline run so the
                # S1 attractor + external S2 classify actually happen (that is the
                # only path that writes a teacher row; see _record_s2_teacher_sample).
                print("[p5-tool-call] text-only answer, deferring to full_pipeline", flush=True)
                _p5 = None
            if _p5 is not None:
                # 2026-11-03: 必须先取出来。写成 "verdict": ... if result.get(...)
                # 会在字典字面量内部引用尚未赋值的 result —— 此时 result 仍是 None
                # (上面 if result is None 的分支), 于是 'NoneType' object has no
                # attribute 'get' → P5 分支整段崩掉并回落 full_pipeline
                # (实测: 每次都 [p5-tool-call] pre-step skipped: 'NoneType' ...)。
                _p5_execs = list(_p5.get("tool_executions") or [])
                result = {
                    "query": query,
                    "response": _p5.get("response", ""),
                    "tool_executions": _p5_execs,
                    "llm_route": _p5.get("llm_route", "tool_call"),
                    # 2026-10-04 credit-loop: forward the decision-prompt marker.
                    # stepfun_tool_caller sets it for MC world decisions, but this
                    # dict was built field-by-field and dropped it -- so the
                    # teacher-registration branch below (which reads
                    # _p5["decision_prompt"]) never fired for any of the 6770
                    # detected decision turns.
                    "decision_prompt": bool(_p5.get("decision_prompt")),
                    # 2026-11-03: these four were hardcoded literals. P5 bypasses
                    # full_pipeline, so there is no S1/S2 agreement signal to report
                    # -- claiming confidence 1.0 did not just lie in the response,
                    # it fed "the external teacher is always certain" into
                    # _record_s2_shadow (external_confidence_sum) and into every
                    # stage4 teacher sample (which capped internalization weight at
                    # 1.0). verdict is now derived from what actually ran; the rest
                    # is honestly unknown: None == "not measured".
                    "verdict": "tool_call" if _p5_execs else "text",
                    "confidence": None,
                    "margin": None,
                    "temporal_bias": None,
                    "confidence_source": "unavailable_p5_bypass",
                    "act": _act_meta,
                }
                # P5 is an external StepFun decision path too.  It bypasses
                # full_pipeline, so register its exact job ID here or a later
                # measured /feedback can never close the teacher sample.
                # 2026-10-02 credit-loop fix: decision-prompt jobs (MC bridge)
                # carry tool_executions=[] — their action runs in the world and
                # the bridge posts measured /feedback under job_id. Register
                # those too, or the world outcome joins no teacher sample.
                _p5_decision = bool(_p5.get("decision_prompt"))
                if result["tool_executions"] or _p5_decision:
                    try:
                        if _p5_decision:
                            _p5_type = _p5_decision_attractor_type(result.get("response", ""))
                            _p5_source = "p5_decision_world"
                            _p5_joinable = True
                        else:
                            _p5_tools = [str(e.get("tool") or "")
                                         for e in result["tool_executions"]]
                            _p5_type = "sensory" if any(
                                t in {"mc_world_state", "get_self_status", "look_around",
                                      "scan_nearby_entities", "check_status"}
                                for t in _p5_tools
                            ) else "memory" if any(t == "recall_memory" for t in _p5_tools) else "action"
                            _p5_source = "p5_external_tool_call"
                            # 2026-10-04 credit-loop: tool-call jobs are measured
                            # decisions too (bridge posts /feedback under job_id),
                            # so they must carry the real attractor type — a hardcoded
                            # "unknown" made the eligibility gate reject every row.
                            _p5_joinable = True
                        if _s2_source_has_independent_teacher(_p5_source):
                            _p5_teacher = _record_s2_teacher_sample(
                                query=query,
                                attractor={"dominant_type": _p5_type,
                                           "concentration": 0.0,
                                           "competition": 0.0, "stability": 0.0,
                                           "type_counts": {}},
                                # 2026-11-03: was a hardcoded 1.0 -> every P5 teacher
                                # sample claimed maximal confidence, and
                                # stage4_s2_internalization caps its weight ceiling on
                                # this value. None = not measured; stage4 already
                                # coerces None to its 0.5 default.
                                external_result={"type": _p5_type, "confidence": None},
                                tick=RESTING_STATE.get("tick", 0),
                                decision_id=job_id,
                                teacher_source=_p5_source,
                                teacher_joinable=_p5_joinable,
                            )
                            if _p5_teacher:
                                result["s2_teacher_sample"] = _p5_teacher
                        # 2026-10-07: alias the P5 job id to the job id in the
                        # teacher namespace, for EVERY route through this block
                        # (tool_executions or decision prompt) -- not just the
                        # ones that registered a teacher row. A measured
                        # /feedback resolves _last_p5_job -> decision_id against
                        # action_impact rows; the target must exist regardless.
                        # action_impact.jsonl keys rows by action_id (l5g-...)
                        # while teacher rows key by decision_id (P5 job id) --
                        # without this bridge a measured /feedback can never
                        # close the teacher sample.
                        RESTING_STATE["_last_p5_job"] = {
                            "decision_id": job_id, "tick": RESTING_STATE.get("tick", 0),
                        }
                    except Exception as _p5_teacher_error:
                        print(f"[s2-teacher] P5 registration skipped: {_p5_teacher_error}", flush=True)
                print(f"[p5-tool-call] LLM routed {len(result['tool_executions'])} tool(s): "
                      f"{[e['tool'] for e in result['tool_executions']]}", flush=True)
        except Exception as _p5e:
            print(f"[p5-tool-call] pre-step skipped: {_p5e}", flush=True)
        _t_pre = time.time() - _tt0
        _tp0 = time.time()
        if result is None:
            result = full_pipeline(
                query, depth=depth, fast=fast, decision_id=job_id,
                teacher_joinable=True,
            )
            result.setdefault("llm_route", "full_pipeline")
        _t_pipe = time.time() - _tp0
        print(f"[job-timing] {job_id} fast={fast} skip_p5={skip_p5} pre={_t_pre:.1f}s pipeline={_t_pipe:.1f}s total={time.time()-_tt0:.1f}s", flush=True)
        print(f"[job-pipeline-returned] {job_id} keys={list(result.keys())[:8]}", flush=True)
        result["decision_id"] = job_id
        try:
            from tool_router import upsert_decision_envelope, get_decision_envelope
            upsert_decision_envelope(
                job_id,
                route=result.get("llm_route") or "full_pipeline",
                state_before={"query": str(query)[:2000]},
            )
            result["decision_envelope"] = get_decision_envelope(job_id)
        except Exception as _envelope_error:
            result["decision_envelope_error"] = f"{type(_envelope_error).__name__}: {_envelope_error}"
        if not result.get("skipped"):
            # l5g-20260828-toolcall-verdict-guard: tool_call-routed results have
            # no aggregator block; the unconditional overwrite below clobbered
            # their top-level verdict/confidence (set at L32-42) with
            # agg.get(...)=None, which made every tool-routed answer surface as
            # DISAGREED|0 in contemplate.ps1. Only derive from the aggregator
            # when one exists; preserve P5's own verdict/confidence otherwise.
            agg = result.get('aggregator', {})
            if agg:
                result['verdict'] = agg.get('verdict')
                result['confidence'] = agg.get('final_confidence')
                result['margin'] = agg.get('winner_margin')
                result['temporal_bias'] = agg.get('temporal_bias')
            resp_text = result.get('response', '')
            if resp_text:
                result['response'] = resp_text
            # P2: L10 action dispatcher — ego's own contemplate output may
            # carry a tool intent (e.g. "build stone at 10,64,-5"). Route it
            # through the SAME unified tool_router (source=internal_l10) so
            # ego's cognition and action stay in one loop, and every call is
            # recorded in the shared memory log. Best-effort only: failures
            # are swallowed, never break the pipeline.
            # P2 dedupe: P5 already executed this decision's tool call. Its
            # natural-language response is a report, not a second intent.
            if not result.get("tool_executions"):
                try:
                    from l10_action_dispatcher import dispatch_to_tool_router
                    _tool_execs = dispatch_to_tool_router(
                        resp_text, source="internal_l10", decision_id=job_id
                    )
                    if _tool_execs:
                        result['tool_executions'] = _tool_execs
                        print(f"[l10-dispatch] {len(_tool_execs)} tool(s) executed: "
                              f"{[e['tool'] for e in _tool_execs]}", flush=True)
                except Exception as _te:
                    print(f"[l10-dispatch] skipped: {_te}", flush=True)
            else:
                print("[l10-dispatch] skipped: P5 already executed tool(s)", flush=True)
            result['act'] = _act_meta
            # L10 may have appended tool actions after the initial envelope write.
            # Re-read after dispatch so the HTTP result is the final snapshot.
            try:
                from tool_router import get_decision_envelope
                result["decision_envelope"] = get_decision_envelope(job_id)
            except Exception as _envelope_error:
                result["decision_envelope_error"] = f"{type(_envelope_error).__name__}: {_envelope_error}"
        with _JOB_LOCK:
            _CONTEMPLATE_JOBS[job_id] = {"status": "done", "result": result, "created": _CONTEMPLATE_JOBS.get(job_id, {}).get("created", time.time())}
            _job_persist(job_id, _CONTEMPLATE_JOBS[job_id])
            _job_evict()
        print(f"[job-done] {job_id} s1={result.get('system1',{}).get('dominant_type','?')} verdict={result.get('verdict','?')}", flush=True)
    except Exception as _e:
        import traceback
        print(f"[job-err] {job_id} {_e}", flush=True)
        traceback.print_exc()
        with _JOB_LOCK:
            _CONTEMPLATE_JOBS[job_id] = {"status": "error", "error": str(_e), "created": time.time()}
            _job_evict()

