# l6p 2026-09-15 "diagnose the diagnoser": lazy cached telemetry self-check
# (split-brain / freshness / roundtrip / stale repair state), refreshed at
# most every 300s regardless of /status poll rate.
import threading as _tsc_threading
_TSC_CACHE = {"ts": 0.0, "result": None}
_TSC_LOCK = _tsc_threading.Lock()

def _lazy_telemetry_selfcheck(max_age_s: float = 300.0):
    if _run_telemetry_selfcheck is None:
        return {"status": "unavailable"}
    now = time.time()
    if _TSC_CACHE["result"] is not None and now - _TSC_CACHE["ts"] < max_age_s:
        return _TSC_CACHE["result"]
    with _TSC_LOCK:
        if _TSC_CACHE["result"] is not None and time.time() - _TSC_CACHE["ts"] < max_age_s:
            return _TSC_CACHE["result"]
        try:
            _TSC_CACHE["result"] = _run_telemetry_selfcheck()
        except Exception as _tsc_err:
            _TSC_CACHE["result"] = {"status": "error", "error": str(_tsc_err)}
        _TSC_CACHE["ts"] = time.time()
        return _TSC_CACHE["result"]

