_CAUSAL_EVENTS_PATH = WORKSPACE / ".lae" / "causal_events.jsonl"
_CAUSAL_NOOP_SKIPPED = 0   # 2026-09-11: 被丢弃的"无变化"事件计数

_CST_TZ = __import__("datetime").timezone(__import__("datetime").timedelta(hours=8))


def _write_causal_event(causal_tag: str, pre: dict, post: dict):
    """Append one immutable causal event to .lae/causal_events.jsonl.

    2026-09-11: pre == post 的事件直接丢弃。实测 comm_unfreeze 3179/3179、
    proprio_spike 1684/1684 全是"记了一笔但前后状态一模一样"，占全库 72%，
    下游任何因果统计都会被它泡成噪声。真正的事件 = 变化。
    """
    global _CAUSAL_NOOP_SKIPPED
    try:
        if pre == post:
            _CAUSAL_NOOP_SKIPPED += 1
            if _CAUSAL_NOOP_SKIPPED % 200 == 1:
                print(f"[causal_events] noop skipped x{_CAUSAL_NOOP_SKIPPED} (tag={causal_tag})", flush=True)
            return
        tick = int(RESTING_STATE.get("tick", 0) or 0)
        entry = {
            "schema": "causal_event.v1",
            "tick": tick,
            "ts": __import__("datetime").datetime.now(_CST_TZ).isoformat(),
            "causal_tag": causal_tag,
            "pre": pre,
            "post": post,
        }
        with open(str(_CAUSAL_EVENTS_PATH), "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
    except Exception as _ce_err:
        print(f"[causal_events] write failed: {_ce_err}", flush=True)


def _read_recent_causal_events(n: int = 3) -> list:
    """Read last n causal events from .lae/causal_events.jsonl."""
    try:
        if not _CAUSAL_EVENTS_PATH.exists():
            return []
        lines = _CAUSAL_EVENTS_PATH.read_text(encoding="utf-8").strip().splitlines()
        events = []
        for line in lines[-n:]:
            try:
                events.append(json.loads(line))
            except Exception:
                continue
        return events
    except Exception:
        return []

