# P3 helper functions (2026-08-18)
def _get_primary_role(nid: str, default: str = "meta") -> str:
    """Get the highest-scoring role for a neuron. Fast path for routing/logic."""
    rs = NEURON_TYPE.get(nid)
    if isinstance(rs, dict) and rs:
        return max(rs, key=rs.get)
    return default

def _get_role_score(nid: str, role: str, default: float = 0.0) -> float:
    """Get score for a specific role. Returns 0.0 if neuron has no such role."""
    rs = NEURON_TYPE.get(nid)
    if isinstance(rs, dict):
        return rs.get(role, default)
    return default

def _has_role_above(nid: str, role: str, threshold: float = 0.3) -> bool:
    """Check if neuron has a specific role above threshold."""
    return _get_role_score(nid, role) >= threshold


# P3 helper (2026-08-18): extract primary role from role_scores
def _get_primary_role_from_scores(role_scores):
    """Return highest-scoring role key from a role_scores dict."""
    if isinstance(role_scores, dict) and role_scores:
        return max(role_scores, key=role_scores.get)
    return "meta"

def _filter_by_role(neuron_dict, role):
    """Filter neuron dict by primary role. neuron_dict: {nid: role_scores}."""
    return [nid for nid, scores in neuron_dict.items() 
            if isinstance(scores, dict) and _get_primary_role_from_scores(scores) == role]


def _diverse_candidate_ids(ids, limit, *, per_type=4, rng=None, leader=None, leader_level=0):
    """Return bounded round-robin candidates so one neuron type cannot monopolize seeds."""
    if limit <= 0 or not ids:
        return []
    rng = rng or random
    buckets = {}
    seen = set()
    # Stable dedupe is required because older hot-pool appenders could write
    # the same episodic/slot ID more than once.
    for nid in ids:
        key = str(nid)
        if key in seen:
            continue
        seen.add(key)
        # l5g-20261031-062240: bucket by the role map, not the birth prefix.
        # Measured on the live 2000-slot hot pool: the prefix key gave curiosity
        # 4 slots / 0.40% of per-tick seed candidates while the role map assigns
        # 91 slots / 5.88%; the primary-role default was computed then discarded
        # whenever the prefix parsed, hiding 190k curated overrides.
        typ = _get_primary_role(key)
        buckets.setdefault(typ, []).append(nid)
    for values in buckets.values():
        rng.shuffle(values)
    types = list(buckets)
    rng.shuffle(types)
    out = []
    # Proportional per-type allocation: each type gets a share proportional to its
    # bucket size (and therefore its cached population). A fairness floor of 2 per type
    # is preserved so small types are not zeroed out. Replaces the old flat per_type=4
    # hard cap that caused large cached types (action, doubt) to be 10-30x under-represented.
    total_in_buckets = sum(len(v) for v in buckets.values())
    # R2 load-violation-only capping (l5g-20261101-063851): only the leading
    # type may exceed the flat round-robin share; its allowance anneals with
    # the persistent low-concentration streak and is monopoly-bounded at half
    # the pool. Non-leaders keep the flat per_type fairness untouched.
    _leader_cap = max(2, limit // 2) if (leader and leader_level > 0) else 0
    # l5g-20261102-064978: the anneal must bound the leader TOTAL pool share.
    # A flat per-round +level allowance re-serves every round (~limit//75
    # rounds), which at the live top_k=900 capped the leader near 12% of
    # seeds and concentration never left the 0.10-0.13 plateau (measured
    # 164 ticks this generation). Express the anneal as a share of the
    # pool: 5% per level, front-loaded per round, never weaker than the
    # old allowance reach, still bounded by _leader_cap (half pool) and
    # the live type_dominance_cap activation clip downstream.
    _leader_share_cap = max(int(limit * 0.05 * leader_level), (per_type + leader_level) * max(1, limit // 75)) if (leader and leader_level > 0) else 0
    _leader_taken = 0
    while types and len(out) < limit:
        next_types = []
        for typ in types:
            values = buckets[typ]
            if total_in_buckets > 0:
                fair = max(2, min(per_type, int(len(values) / total_in_buckets * limit)))
            else:
                fair = len(values)
            if typ == leader and _leader_cap:
                fair = max(0, min(max(per_type + leader_level, _leader_share_cap), _leader_cap - _leader_taken, _leader_share_cap - _leader_taken))
            take = min(fair, len(values), limit - len(out))
            out.extend(values[:take])
            if typ == leader:
                _leader_taken += take
            del values[:take]
            if values and len(out) < limit and take > 0:
                next_types.append(typ)
            if len(out) >= limit:
                break
        types = next_types
    return out


def _adaptive_per_type():
    """Adaptive per-type equalizer cap (pre-registered l5g-20261031-062881).

    Standing rule: per_type 4 -> 2 while stagnation_streak >= 5 (rare types
    get a fairer shot at seed slots); restore to 4 once the 8-tick dominant
    transition rate holds >= 0.60 for 8 consecutive ticks. Resting
    candidate/seed pools only; hot-id call sites are untouched.
    """
    st = RESTING_STATE.get("adaptive_eq")
    if st is None:
        st = {"armed": False, "restore_streak": 0}
        RESTING_STATE["adaptive_eq"] = st
    if int(RESTING_STATE.get("stagnation_streak", 0) or 0) >= 5:
        st["armed"] = True
        st["restore_streak"] = 0
        return 2
    if st["armed"]:
        _recent = (RESTING_STATE.get("trajectory") or [])[-8:]
        _flips = sum(
            1 for _i in range(1, len(_recent))
            if _recent[_i].get("dominant") != _recent[_i - 1].get("dominant")
        )
        _rate = _flips / max(1, len(_recent) - 1)
        st["restore_streak"] = st["restore_streak"] + 1 if _rate >= 0.60 else 0
        if st["restore_streak"] >= 8:
            st["armed"] = False
            st["restore_streak"] = 0
    return 2 if st["armed"] else 4


def _get_type_for_prefix(nid: str, default: str = "meta") -> str:
    """Legacy compatibility: extract type from nid prefix (e.g., 'n-action-1029' -> 'action')."""
    if "-" in nid:
        parts = nid.split("-")
        if len(parts) >= 2 and parts[1] in TYPE_NAMES:
            return parts[1]
    return default
