def _publish_dominant_channel(channel: str, value: str, *, source: str,
                              concentration=None, competition=None, metadata=None) -> dict:
    """Single writer for the four dominant-state channels.

    observed_raw: immutable KWTA observation for this tick.
    arbitration_candidate: pre-policy behavioral proposal.
    behavioral: final post-policy action mode.
    identity: long-window descriptive profile, never a control input.
    """
    if channel not in {"observed_raw", "arbitration_candidate", "behavioral", "identity"}:
        raise ValueError(f"unknown dominant channel: {channel}")
    record = {
        "value": str(value or "unknown"),
        "tick": int(RESTING_STATE.get("tick", 0) or 0),
        "source": str(source),
    }
    if concentration is not None:
        record["concentration"] = round(float(concentration), 4)
    if competition is not None:
        record["competition"] = round(float(competition), 4)
    if metadata:
        record["metadata"] = dict(metadata)
    channels = RESTING_STATE.setdefault("dominant_channels", {})
    channels[channel] = record

    # Backward-compatible mirrors. No other live code may assign these fields.
    if channel == "observed_raw":
        RESTING_STATE["raw_attractor_dominant"] = record["value"]
        if concentration is not None:
            RESTING_STATE["raw_attractor_concentration"] = float(concentration)
        if competition is not None:
            RESTING_STATE["raw_attractor_competition"] = float(competition)
    elif channel == "behavioral":
        RESTING_STATE["last_dominant"] = record["value"]
    return record


def _vote_behavioral_dominant(result, value, *, source, reason):
    """Single arbitration entry point for behavioral dominant writes.

    P2: rule_mod gate, min-dwell, and tripwire all express their decision
    through this vote recorder instead of writing result["dominant"] directly.
    The call is order-preserving (writes immediately so mid-tick readers see
    the current decision), and every vote is logged in
    RESTING_STATE["_arbitration_votes"] for the per-tick arbitration audit.
    """
    value = str(value or "unknown")
    # l5g-20261101-064078-FIX: close the rule_modification stagnation-gate bypass hole.
    # The rm gate at line ~16628 only inspects result["dominant"] (the attractor
    # winner) and is dead code in the current selector regime: measured 2026-11-01,
    # 30/30 recent [min_dwell] log events vote rule_modification with zero
    # [rule_mod_gate] lines, and live samples at ticks 64155-64159 show
    # resting_dominant=rule_modification with stagnation_streak=0 while
    # raw_attractor_dominant=integrator -- the exact state the gate forbids
    # ("only allow dominance when stagnation >= 1"). This function is the single
    # arbitration entry point for every behavioral dominant write, so enforce the
    # gate here: refuse rule_modification while stagnation_streak < 1 and no freq
    # bypass is active (keep the incumbent). The original gate's
    # _int_press_counter>0 exemption is deliberately not carried over: measured
    # 13-19 this session, it would make this guard dead code.
    # l5g-20261104-065586: oscillation escape for the rm stagnation gate.
    # Measured 2026-11-04, window ticks 65517-65585 (n=84 from
    # .lae/neural_snapshots.jsonl): the gate refuses rule_modification while
    # stagnation_streak<1, but the streak reads 0 on 47.6% of window ticks
    # because the crown rotates (shift density 4.286/10, transition_rate_8
    # mean 0.443, 55/84 ticks >=0.4) before any streak can build - the gate's
    # permission condition is starved by the very rotation rm is meant to
    # break. Live tick 65586: min_dwell voted allow (late_crisis), gate vetoed
    # it (vote reason rm_stagnation_gate_refused:early_allow:late_crisis).
    # Escape band competition>=0.85 AND concentration<=0.15 = measured stuck
    # regime (window means 0.8866/0.1141; live 0.9305/0.1148). Callers that
    # lack the keys default to 0.0 -> escape False -> behavior unchanged.
    _rm_osc_escape = (float(result.get("competition", 0.0) or 0.0) >= 0.85
                      and float(result.get("concentration", 0.0) or 0.0) <= 0.15)
    if (value == "rule_modification"
            and int(RESTING_STATE.get("stagnation_streak", 0) or 0) < 1
            and int(RESTING_STATE.get("_rule_mod_freq_bypass", 0) or 0) < 1
            and not _rm_osc_escape):
        value = str(result.get("dominant") or "unknown")
        reason = "rm_stagnation_gate_refused:" + str(reason)
    votes = RESTING_STATE.setdefault("_arbitration_votes", [])
    votes.append({
        "tick": int(RESTING_STATE.get("tick", 0) or 0),
        "value": value,
        "source": str(source),
        "reason": str(reason),
    })
    result["dominant"] = value
    return value


