def _s2_query_is_low_risk(query: str) -> bool:
    """Return whether a local S2 result may be considered for a future gate.

    This is deliberately conservative: world actions, tool calls, current
    facts, and code changes remain external-LLM territory until measured.
    """
    text = str(query or "").lower()
    risky_terms = (
        "attack", "build", "craft", "move", "goto", "mine", "tool", "execute",
        "action", "minecraft", "世界", "坐标", "生物", "攻击", "建造", "挖矿",
        "最新", "今天", "当前", "新闻", "价格", "代码", "修复", "修改",
    )
    return not any(term in text for term in risky_terms)


def _s2_load_semantic_prototypes():
    """Load only verified low-risk teacher queries as shadow prototypes."""
    path = S2_TRAINING_DATASET_PATH
    try:
        mtime_ns = path.stat().st_mtime_ns
    except OSError:
        mtime_ns = None
    if _S2_SEMANTIC_CACHE["mtime_ns"] == mtime_ns:
        return _S2_SEMANTIC_CACHE["prototypes"]
    with _S2_SEMANTIC_CACHE_LOCK:
        if _S2_SEMANTIC_CACHE["mtime_ns"] == mtime_ns:
            return _S2_SEMANTIC_CACHE["prototypes"]
        prototypes = []
        if mtime_ns is not None:
            try:
                rows = path.read_text(encoding="utf-8", errors="replace").splitlines()
            except OSError:
                rows = []
            for raw in rows:
                try:
                    item = json.loads(raw)
                    query = str(item.get("query") or "")
                    teacher = item.get("teacher") or {}
                    outcome = item.get("actual_outcome") or {}
                    # 2026-11-09 (l5g-20261109-068583): prototypes below are
                    # shadow-only (gate_eligible False); the low-risk gate here
                    # passed 4/3038 measured dataset rows and starved the
                    # semantic channel to chance accuracy (0.0599). Drop it,
                    # keep the verified-outcome and confidence>=0.8 gates.
                    if (
                        not query
                        or str(outcome.get("outcome") or "").lower() not in {"success", "correct", "verified"}
                        or float(teacher.get("confidence") or 0.0) < 0.8
                    ):
                        continue
                    vector = get_embedding(query)
                    if vector:
                        prototypes.append({
                            "neuron_id": item.get("decision_id") or "s2-prototype",
                            "s2_type": str(teacher.get("type") or "unknown"),
                            "s1_type": str((item.get("s1") or {}).get("type") or "unknown"),
                            "vector": vector,
                        })
                except (TypeError, ValueError, json.JSONDecodeError):
                    continue
        _S2_SEMANTIC_CACHE.update({"mtime_ns": mtime_ns, "prototypes": prototypes})
        S2_SEMANTIC_STATS["prototypes"] = len(prototypes)
        S2_SEMANTIC_STATS["cache_status"] = "ready" if prototypes else "empty"
        return prototypes


def _s2_semantic_prediction(query, embedding):
    """Return a shadow-only S2 prediction from the nearest verified prototype."""
    if not S2_SEMANTIC_SHADOW_ENABLED or not _s2_query_is_low_risk(query) or not embedding:
        return None
    prototypes = _s2_load_semantic_prototypes()
    S2_SEMANTIC_STATS["queries"] += 1
    best = None
    best_similarity = -1.0
    query_vector = np.asarray(embedding, dtype=np.float32)
    query_norm = float(np.linalg.norm(query_vector))
    if query_norm <= 0.0:
        return None
    for prototype in prototypes:
        prototype_vector = np.asarray(prototype["vector"], dtype=np.float32)
        prototype_norm = float(np.linalg.norm(prototype_vector))
        if prototype_norm <= 0.0 or prototype_vector.shape != query_vector.shape:
            continue
        similarity = float(np.dot(query_vector, prototype_vector) / (query_norm * prototype_norm))
        if similarity > best_similarity:
            best_similarity = similarity
            best = prototype
    S2_SEMANTIC_STATS["last_similarity"] = round(max(0.0, best_similarity), 4) if best else None
    if not best or best_similarity < S2_SEMANTIC_MIN_SIMILARITY:
        return None
    S2_SEMANTIC_STATS["matches"] += 1
    return {
        "neuron_id": best["neuron_id"],
        "type": best["s2_type"],
        "s2_type": best["s2_type"],
        "confidence": round(best_similarity, 4),
        "match_source": "semantic_prototype",
        "semantic_similarity": round(best_similarity, 4),
        "gate_eligible": False,
    }


def _record_s2_shadow(*, query, local_prediction, external_result, tick, decision_id=""):
    """Append one local-vs-external S2 comparison without affecting control."""
    try:
        local_type = str((local_prediction or {}).get("type") or "unknown")
        external_type = str((external_result or {}).get("type") or "unknown")
        # 2026-11-03: confidence can legitimately be None ("not measured" — the P5
        # tool path has no S1/S2 agreement signal). Coercing None to 0.0 reports
        # the teacher as zero-confident, and the old hardcoded 1.0 reported it as
        # always certain; neither is data. Skip such samples in the sums and count
        # them separately so the comparison stays honest.
        _lc = (local_prediction or {}).get("confidence")
        _ec = (external_result or {}).get("confidence")
        local_conf = float(_lc) if _lc is not None else None
        external_conf = float(_ec) if _ec is not None else None
        low_risk = _s2_query_is_low_risk(query)
        matched = local_type == external_type and local_type != "unknown"
        S2_SHADOW_STATS["samples"] += 1
        S2_SHADOW_STATS["matches"] += int(matched)
        S2_SHADOW_STATS["mismatches"] += int(not matched)
        S2_SHADOW_STATS["low_risk_samples"] += int(low_risk)
        if local_conf is not None:
            S2_SHADOW_STATS["local_confidence_sum"] += local_conf
        if external_conf is not None:
            S2_SHADOW_STATS["external_confidence_sum"] += external_conf
        if local_conf is None or external_conf is None:
            S2_SHADOW_STATS["confidence_unmeasured_samples"] = \
                S2_SHADOW_STATS.get("confidence_unmeasured_samples", 0) + 1
        S2_SHADOW_STATS["last_tick"] = tick
        S2_SHADOW_STATS["last_sample_ts"] = time.strftime("%Y-%m-%d %H:%M:%S")
        entry = {
            "schema": "s2_shadow.v1",
            "ts": S2_SHADOW_STATS["last_sample_ts"],
            "tick": tick,
            "decision_id": decision_id or None,
            "query_hash": hashlib.sha256(str(query).encode("utf-8")).hexdigest()[:16],
            "query_risk": "low" if low_risk else "high_or_unknown",
            "local": {
                "type": local_type,
                "confidence": round(local_conf, 4) if local_conf is not None else None,
                "reasoning_neuron": (local_prediction or {}).get("neuron_id"),
                "source": (local_prediction or {}).get("source", "keyword"),
                "semantic_similarity": (local_prediction or {}).get("semantic_similarity"),
            },
            "external": {"type": external_type,
                         "confidence": round(external_conf, 4) if external_conf is not None else None},
            "matched": matched,
            "control": "external_s2",
        }
        S2_SHADOW_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        _rotate_jsonl(S2_SHADOW_LOG_PATH)
        with open(S2_SHADOW_LOG_PATH, "a", encoding="utf-8") as handle:
            handle.write(json.dumps(entry, ensure_ascii=False) + "\n")
        return entry
    except Exception as exc:
        print(f"[s2-shadow] record skipped: {exc}", flush=True)
        return None


# 2026-10-02 credit-loop: one lock for the teacher log's three writers
# (record / complete / expire) — append-vs-rewrite races silently dropped rows.
_S2_TEACHER_FILE_LOCK = threading.Lock()


def _s2_source_has_independent_teacher(teacher_source: str) -> bool:
    """True iff this path's teacher type is NOT derived from the decision itself.

    Root cause (audited 2026-10-07, 158/158 completed rows): every
    ``p5_*`` row got teacher.type == s1.type because both sides come from the
    SAME tool-name table. The old guard rejected on *value equality*, so these
    rows simply never registered — 623/781 expired, 247 of them fp-* ids the
    bridge can't even address. The correct discriminator is the SOURCE, not the
    value: only ``full_pipeline`` pairs a neural-run attractor with an external
    classifier label. No tool-call path ever will, so don't gate on values
    there; drop the row instead of registering a teacher that is its own echo.
    """
    return teacher_source == "full_pipeline_external_s2"


def _record_s2_teacher_sample(*, query, attractor, external_result, tick,
                              decision_id="", teacher_source="full_pipeline_external_s2",
                              teacher_joinable=False):
    """Persist an S2 label; only joinable external jobs may train locally.

    A teacher label that merely echoes the S1 attractor label is not evidence:
    the 2026-10-05 audit found 1685/1691 stored samples had teacher.type ==
    s1.type because the P5 tool-call path derives BOTH sides from the same
    tool-name table (tl_ego_server.py:203-211) -- there is no independent
    teacher there. Such rows would train the local S2 matcher to reproduce
    S1's own answers with high confidence, which is worse than no model.
    full_pipeline is unaffected: its attractor comes from the neural run and
    its teacher from the external classifier, so disagreement survives.
    """
    try:
        # 2026-10-07: gate on the SOURCE, not on the value. The value gate let
        # every p5_decision_world row through (both sides computed by the same
        # helper) while rejecting nothing real -- it starved the pool instead
        # of stopping the self-teaching.
        if not _s2_source_has_independent_teacher(teacher_source):
            print(f"[s2-teacher] no independent teacher on {teacher_source}, "
                  f"not registering did={decision_id}", flush=True)
            return None
        training_eligible = (
            teacher_joinable
            # 2026-10-04: p5_external_tool_call joins the whitelist. Tool-call
            # jobs are measured decisions too (the bridge posts /feedback under
            # their job_id), so keeping them out starved the training pool to zero.
            and teacher_source in ("full_pipeline_external_s2", "p5_decision_world",
                                   "p5_external_tool_call")
            and bool(str(decision_id or "").strip())
            and str((attractor or {}).get("dominant_type") or "unknown") not in {"", "unknown"}
        )
        entry = {
            "schema": "s2_teacher_sample.v1",
            "source": teacher_source,
            "training_eligible": training_eligible,
            "ts": time.strftime("%Y-%m-%d %H:%M:%S"),
            "tick": tick,
            "decision_id": decision_id or None,
            "query_hash": hashlib.sha256(str(query).encode("utf-8")).hexdigest()[:16],
            "query_excerpt": str(query or "")[:4000],
            "s1": {
                "type": attractor.get("dominant_type", "unknown"),
                "concentration": attractor.get("concentration"),
                "competition": attractor.get("competition"),
                "stability": attractor.get("stability"),
                "type_counts": dict(attractor.get("type_counts", {}) or {}),
            },
            "teacher": {
                "type": str((external_result or {}).get("type") or "unknown"),
                # 2026-11-03: None = not measured (see the P5 result dict). Writing
                # the old hardcoded 1.0 here capped every stage4 internalization
                # weight at maximum for tool-routed decisions.
                "confidence": ((_ec if (_ec := (external_result or {}).get("confidence")) is None
                                else float(_ec))),
            },
            "actual_outcome": None,
            "status": "pending_outcome",
        }
        S2_TEACHER_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        with _S2_TEACHER_FILE_LOCK:
            _rotate_jsonl(S2_TEACHER_LOG_PATH)
            with open(S2_TEACHER_LOG_PATH, "a", encoding="utf-8") as handle:
                handle.write(json.dumps(entry, ensure_ascii=False) + "\n")
        # 2026-11-08 (P1 S2 供给): _last_p5_job is the single slot the action tracker
        # stamps onto impact rows so a measured outcome can close this row. It was
        # only set on the P5 pre-step route, so decisions taking any other route
        # left a stale id behind (measured: today's 160 teacher decision_ids had a
        # 0/160 intersection with action_impact decision_ids). Keep it current here,
        # where every teacher row is actually written.
        if decision_id:
            try:
                RESTING_STATE["_last_p5_job"] = {
                    "decision_id": str(decision_id),
                    "tick": RESTING_STATE.get("tick", 0),
                }
                _s2_did = str(decision_id)
                if _s2_did not in _S2_PENDING_DECISIONS:
                    _S2_PENDING_DECISIONS.append(_s2_did)
                    del _S2_PENDING_DECISIONS[:-10]
            except Exception:
                pass
        # 2026-11-13 (l5g-20261113-072318, P1 S2 join): the goal text ego
        # contemplates names THIS row's own goal_id, but the tracker entry for
        # that goal was stamped at externalize time with an OLDER pending
        # decision id (FIFO drain). Measured: 21/21 goal-bearing completed
        # teacher rows were crossed wires -- goal X's label closed with goal
        # Y's measured outcome, join_accuracy 0.0, live on the current boot.
        # Re-stamp any live tracker entry for the goal named in THIS query so
        # the 5-tick impact window closes the row it belongs to.
        try:
            _q_goal_ids = set(re.findall(r"l5g-\d+-\d+", str(query or "")))
            if _q_goal_ids and decision_id:
                for _trk in ACTION_TRACKER:
                    if _trk.get("action_id") in _q_goal_ids:
                        _trk["decision_id"] = str(decision_id)
        except Exception:
            pass
        return entry
    except Exception as exc:
        print(f"[s2-teacher] record skipped: {exc}", flush=True)
        return None


def _recent_measured_feedback(feedback_log, limit=10):
    """Return only externally measured task outcomes for decision context."""
    if not isinstance(feedback_log, list) or limit <= 0:
        return []
    measured = [
        entry for entry in feedback_log
        if isinstance(entry, dict)
        and entry.get("measured") is True
        and entry.get("outcome") != "self_contemplation"
    ]
    return measured[-limit:]


def _relevant_gate3_failures(entries, goal_type: str, goal_text: str,
                             now_ts: float | None = None, max_age_days: int = 7,
                             limit: int = 3) -> list[dict]:
    """Keep only fresh Gate3 failures whose measured criterion matches this goal."""
    import re as _re
    from datetime import datetime as _datetime

    now_ts = time.time() if now_ts is None else float(now_ts)
    target = f"{goal_type} {goal_text}".lower()
    target_tokens = set(_re.findall(r"[a-z0-9]+", target)) - {
        "the", "and", "for", "with", "from", "this", "that", "into",
        "must", "should", "criteria", "success", "metric", "status",
        "observable", "field", "write", "report", "current", "avoid",
        "same", "error", "goal", "task",
    }
    selected = []
    for row in entries if isinstance(entries, list) else []:
        if not isinstance(row, dict) or not isinstance(row.get("failures"), list):
            continue
        stamp = str(row.get("at") or row.get("timestamp") or "").strip()
        try:
            parsed = _datetime.fromisoformat(stamp.replace("Z", "+00:00"))
            if parsed.tzinfo is None:
                parsed = parsed.astimezone()
            age_s = now_ts - parsed.timestamp()
        except (ValueError, OverflowError):
            continue
        if age_s < 0 or age_s > max_age_days * 86400:
            continue

        relevant = []
        for failure in row["failures"]:
            if isinstance(failure, dict):
                evidence = " ".join(str(failure.get(key) or "")
                                    for key in ("metric", "reason"))
            else:
                evidence = str(failure or "")
            tokens = set(_re.findall(r"[a-z0-9]+", evidence.lower()))
            if len(target_tokens & tokens) >= 2:
                relevant.append(failure)
        if relevant:
            selected.append({**row, "failures": relevant})
    selected.sort(key=lambda row: str(row.get("at") or row.get("timestamp") or ""))
    limit = max(0, int(limit))
    return selected[-limit:] if limit else []


def _same_lineage_goal_handoff(lineage_id: str, current_goal_id: str,
                               now_ts: float | None = None, max_age_days: int = 7,
                               max_chars: int = 1200) -> str:
    """Pass a bounded, explicitly unverified artifact from the prior same-lineage goal."""
    import re as _re
    from datetime import datetime as _datetime

    if not _re.fullmatch(r"gl-[0-9a-f]{16}", str(lineage_id or "")):
        return ""
    now_ts = time.time() if now_ts is None else float(now_ts)
    goals, terminals = {}, {}
    try:
        with L5_GOALS_LOG.open("rb") as fh:
            size = fh.seek(0, 2)
            fh.seek(max(0, size - 2_000_000))
            if fh.tell():
                fh.readline()
            lines = fh.readlines()[-2000:]
    except OSError:
        return ""
    for line in lines:
        try:
            row = json.loads(line.decode("utf-8", errors="replace"))
        except (ValueError, TypeError):
            continue
        if not isinstance(row, dict):
            continue
        goal_id = str(row.get("goal_id") or "")
        if not _re.fullmatch(r"l5g-[A-Za-z0-9_-]+", goal_id):
            continue
        if row.get("goal_lineage_id"):
            goals[goal_id] = row
        if row.get("terminal_ts"):
            terminals[goal_id] = row

    candidates = []
    for goal_id, goal in goals.items():
        terminal = terminals.get(goal_id)
        if goal_id == current_goal_id or goal.get("goal_lineage_id") != lineage_id or not terminal:
            continue
        try:
            stamp = _datetime.fromisoformat(str(terminal["terminal_ts"]).replace("Z", "+00:00"))
            if stamp.tzinfo is None:
                stamp = stamp.astimezone()
            ended_at = stamp.timestamp()
        except (ValueError, OverflowError, TypeError):
            continue
        if 0 <= now_ts - ended_at <= max_age_days * 86400:
            candidates.append((ended_at, goal_id, goal, terminal))
    if not candidates:
        return ""

    _, goal_id, goal, terminal = max(candidates, key=lambda item: item[0])
    sandbox_root = (WORKSPACE / "ego_sandbox").resolve()
    if not sandbox_root.is_dir():
        return ""
    try:
        result_path = (sandbox_root / goal_id / "result.json").resolve()
        if not result_path.is_relative_to(sandbox_root) or result_path.stat().st_size > 1_000_000:
            return ""
        result = json.loads(result_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return ""
    if not isinstance(result, dict) or result.get("goal_id") != goal_id:
        return ""

    def bounded(value, limit=360):
        return " ".join(str(value or "").split())[:limit]

    fields = [
        "\n\n[同谱系前序交接：以下来自执行器 result.json，自述内容未经独立验证]",
        f"- goal: {goal_id} ({bounded(goal.get('goal_type'), 80)})",
        f"- lifecycle: {bounded(terminal.get('terminal_state'), 100)}; outcome: {bounded(terminal.get('outcome'), 100)}",
    ]
    for label, key in (("lesson", "lesson"), ("next", "next_impulse_hint")):
        value = bounded(result.get(key))
        if value:
            fields.append(f"- {label}: {value}")
    return "\n".join(fields)[:max(0, int(max_chars))]


def _today_goal_ledger_summary(max_lines: int = 8) -> str:
    """Today's world-readback outcomes grouped by goal_type, for live context.

    2026-10-07: self-review queries pulled stale architecture memories instead
    of today's failures — the contemplation path never saw the live ledger.
    This reads the tail of l5_goal_results.jsonl (evidence_valid rows only,
    today only) and renders a compact success/total line per goal_type,
    worst-first. Best-effort: empty string on any failure. ponytail: tail-scan
    of a 3MB jsonl (~2-4ms/1000 lines); switch to a real daily index if the
    file passes ~50MB.
    """
    try:
        import re as _re
        path = WORKSPACE / ".lae" / "l5_goal_results.jsonl"
        if not path.exists():
            return ""
        today = time.strftime("%Y-%m-%d")
        rows = {}
        with open(path, "r", encoding="utf-8", errors="ignore") as fh:
            for line in fh:
                if "mc_bridge_world_readback" not in line or '"evidence_valid": true' not in line.replace('"evidence_valid":true', '"evidence_valid": true'):
                    continue
                try:
                    o = json.loads(line)
                except Exception:
                    continue
                if not isinstance(o, dict) or o.get("evidence_valid") is not True:
                    continue
                stamp = str(o.get("timestamp") or o.get("created_at") or o.get("ts") or "")
                if today not in stamp:
                    continue
                gt = str(o.get("goal_type") or "?")
                ok, tot = rows.get(gt, (0, 0))
                rows[gt] = (ok + (1 if o.get("outcome") == "success" else 0), tot + 1)
        if not rows:
            return ""
        worst = sorted(rows.items(), key=lambda kv: (kv[1][0] / max(kv[1][1], 1), -kv[1][1]))
        lines = [f"- {gt}: {ok}/{tot} 成功" for gt, (ok, tot) in worst[:max_lines]]
        return ("[今日世界账本 (live, 非记忆) — 失败最多的类型排前]\n" + "\n".join(lines) + "\n\n")
    except Exception:
        return ""


def _measured_action_adaptations_for_goal(goal_type: str, limit: int = 4) -> str:
    """Return relevant strategy advice from verified world readbacks only."""
    relevant = {
        "world_act": {"mc_build", "mc_move", "mc_goto"},
        "world_explore": {"mc_move", "mc_goto", "mc_scan_nearby_entities", "mc_scan_blocks", "mc_look_around"},
        "world_verify": {"mc_scan_nearby_entities", "mc_scan_blocks", "mc_look_around"},
        "action_execute": {"mc_attack", "mc_build", "mc_move", "mc_goto", "mc_eat"},
    }.get(str(goal_type or ""), set())
    if not relevant:
        return ""
    try:
        path = WORKSPACE / ".lae" / "l5_goal_results.jsonl"
        if not path.exists() or limit <= 0:
            return ""
        today = time.strftime("%Y-%m-%d")
        rows = []
        for line in path.read_text(encoding="utf-8", errors="replace").splitlines()[-400:]:
            try:
                item = json.loads(line)
            except Exception:
                continue
            if item.get("evidence_valid") is not True:
                continue
            stamp = str(item.get("timestamp") or item.get("created_at") or item.get("ts") or "")
            if today not in stamp:
                continue
            tool = str(item.get("goal_type") or item.get("tool") or "")
            if tool not in relevant:
                continue
            rows.append({
                "measured": True,
                "tool": tool,
                "outcome": item.get("outcome"),
                "reason": str(item.get("evidence") or item.get("actual_result") or ""),
            })
        notes = _feedback_adaptation_notes(rows, limit=limit)
        if not notes:
            return ""
        return "\n[VERIFIED ACTION ADAPTATIONS - change strategy]\n" + "\n".join(notes) + "\n"
    except Exception:
        return ""


def _feedback_adaptation_notes(feedback_log, limit=4):
    """Turn repeated measured failures into bounded next-step advice.

    This is decision context only: it never executes an action or changes the
    S2 control gate. The bridge often reports only ``reason=...: <tool>``, so
    recover the action name from that field when a typed tool field is absent.
    """
    if not isinstance(feedback_log, list) or limit <= 0:
        return []
    aliases = {"mc_move": "move", "mc_goto": "goto", "mc_attack": "attack",
               "mc_build": "build", "mc_eat": "eat",
               # 2026-10-07: sensory probes failing 100% (look_around 0/75 over
               # two days, scan_blocks 0/40) got only generic advice — same
               # "read state first" tips that tell it to keep probing.
               "mc_look_around": "look_around", "mc_scan_blocks": "scan_blocks",
               "mc_get_self_status": "get_self_status"}
    grouped = {}
    for feedback in feedback_log:
        if not isinstance(feedback, dict) or feedback.get("measured") is not True:
            continue
        outcome = str(feedback.get("outcome") or "").strip().lower()
        action = str(
            feedback.get("tool") or feedback.get("action")
            or feedback.get("action_type") or ""
        ).strip().lower()
        reason = str(feedback.get("reason") or "")
        if not action and "readback:" in reason.lower():
            action = reason.lower().rsplit("readback:", 1)[-1].strip().split()[0]
        action = aliases.get(action, action)
        if not action:
            continue
        grouped.setdefault(action, []).append((outcome, reason))

    notes = []
    for action, rows in grouped.items():
        bad = [row for row in rows if row[0] in {"failed", "failure", "error", "timeout", "partial"}]
        if not bad:
            continue
        latest = rows[-1][0]
        repeated = len(bad) >= 2
        if action in {"move", "goto"}:
            advice = (
                "不要原样重复上一个移动目标；先读取当前位置和可站立高度，"
                "改用当前高度或分段移动，并用世界读回确认后再继续。"
            )
        elif action == "attack":
            advice = (
                "先重新扫描并保留同一个 entity_id，确认距离可达后先靠近再攻击；"
                "目标没掉血或消失都不能算击杀成功。"
            )
        elif action == "build":
            advice = (
                "先检查资源和建造参数，确认 ops 非空且目标位置可放置；"
                "建造失败时不要原样重发同一蓝图。"
            )
        elif action == "eat":
            advice = "先重新检查背包和饥饿状态；食物未被确认存在时不要重复同一个 item_id。"
        elif action in {"look_around", "scan_blocks", "get_self_status"}:
            # 100%-fail probes: the failure is systematic, not parametric —
            # advice must point at the bridge/tool contract, not "probe again".
            advice = (
                "该感知动作已连续全败，属于系统性故障而非参数问题："
                "停止重复调用，改用一次最小验证定位是调用契约(参数/返回解析)坏了"
                "还是世界侧条件不满足，修复前用其他可用感知通道替代。"
            )
        else:
            advice = "先读取该动作的当前状态和失败原因，再选择不同参数或替代动作。"
        prefix = f"{action} 最近出现 {len(bad)} 次部分/失败结果"
        if repeated or latest in {"failed", "failure", "error", "timeout"}:
            notes.append(f"- {prefix}：{advice}")
        if len(notes) >= limit:
            break
    return notes


def _feedback_action_name(feedback: dict) -> str:
    """Normalize an external feedback row to the action that produced it."""
    if not isinstance(feedback, dict):
        return ""
    aliases = {"mc_move": "move", "mc_goto": "goto", "mc_attack": "attack",
               "mc_build": "build", "mc_eat": "eat"}
    action = str(
        feedback.get("tool") or feedback.get("action")
        or feedback.get("action_type") or ""
    ).strip().lower()
    if not action:
        reason = str(feedback.get("reason") or "")
        if "readback:" in reason.lower():
            action = reason.lower().rsplit("readback:", 1)[-1].strip().split()[0]
    return aliases.get(action, action)


def _record_action_feedback_learning(feedback: dict):
    """Feed measured action outcomes into the existing predictive sidecar."""
    if PREDICTIVE_PLASTICITY is None or not isinstance(feedback, dict):
        return {"updated": 0, "reason": "predictive_plasticity_unavailable"}
    action = _feedback_action_name(feedback)
    evidence = (
        feedback.get("evidence") or feedback.get("actual_result")
        or feedback.get("state_after") or feedback.get("world_state")
        or feedback.get("detail") or feedback.get("message") or ""
    )
    state = feedback.get("state_after") or feedback.get("world_state")
    return PREDICTIVE_PLASTICITY.record_action_feedback(
        action,
        feedback.get("outcome"),
        decision_id=feedback.get("decision_id") or feedback.get("action_id") or feedback.get("task_id") or "",
        evidence=evidence,
        state=state if isinstance(state, dict) else None,
    )


def _s2_shadow_status():
    samples = int(S2_SHADOW_STATS.get("samples", 0) or 0)
    return {
        **S2_SHADOW_STATS,
        "accuracy": round(S2_SHADOW_STATS["matches"] / samples, 4) if samples else None,
        "mean_local_confidence": round(S2_SHADOW_STATS["local_confidence_sum"] / samples, 4) if samples else None,
        "mean_external_confidence": round(S2_SHADOW_STATS["external_confidence_sum"] / samples, 4) if samples else None,
        "log_path": str(S2_SHADOW_LOG_PATH),
        "control": "external_s2",
        "shadow_min_confidence": S2_SHADOW_MIN_CONFIDENCE,
        "local_gate_min_confidence": S2_LOCAL_GATE_MIN_CONFIDENCE,
        "semantic": dict(S2_SEMANTIC_STATS),
    }


def _s2_teacher_status():
    """Summarize teacher labels without treating them as verified outcomes."""
    result = {
        "samples": 0,
        "pending_outcome": 0,
        "completed_outcome": 0,
        "expired": 0,
        "training_eligible": 0,
        "completed_training_eligible": 0,
        "teacher_types": {},
        "last_sample_ts": None,
        "log_path": str(S2_TEACHER_LOG_PATH),
    }
    if not S2_TEACHER_LOG_PATH.exists():
        return result
    try:
        for raw in S2_TEACHER_LOG_PATH.read_text(encoding="utf-8", errors="replace").splitlines():
            try:
                item = json.loads(raw)
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            result["samples"] += 1
            status = item.get("status") or "pending_outcome"
            result["pending_outcome"] += int(status == "pending_outcome")
            result["completed_outcome"] += int(status == "completed")
            result["expired"] += int(status == "expired")
            eligible = bool(item.get("training_eligible", False))
            result["training_eligible"] += int(eligible)
            result["completed_training_eligible"] += int(eligible and status == "completed")
            label = str((item.get("teacher") or {}).get("type") or "unknown")
            result["teacher_types"][label] = result["teacher_types"].get(label, 0) + 1
            result["last_sample_ts"] = item.get("ts") or result["last_sample_ts"]
    except OSError:
        pass
    return result


def _append_s2_training_sample(item):
    """Materialize only verified full-pipeline teacher rows for later training."""
    if not item.get("training_eligible") or item.get("status") != "completed":
        return {"written": 0, "reason": "not_training_eligible"}
    # 2026-10-02: aged-out / never-executed rows carry no outcome evidence —
    # keep them out of the dataset so consumers only ever reject real rows.
    if str((item.get("actual_outcome") or {}).get("outcome")) in {"expired", "not_executed"}:
        return {"written": 0, "reason": "non_outcome_status"}
    decision_id = str(item.get("decision_id") or "")
    query = str(item.get("query_excerpt") or "")
    if not decision_id or not query:
        return {"written": 0, "reason": "missing_query_or_decision_id"}
    path = S2_TRAINING_DATASET_PATH
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        existing = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except FileNotFoundError:
        existing = []
    for raw in existing:
        try:
            if json.loads(raw).get("decision_id") == decision_id:
                return {"written": 0, "reason": "already_present", "decision_id": decision_id}
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
    record = {
        "schema": "s2_training_sample.v1",
        "decision_id": decision_id,
        "query": query,
        "s1": item.get("s1") or {},
        "teacher": item.get("teacher") or {},
        "actual_outcome": item.get("actual_outcome") or {},
    }
    with open(path, "a", encoding="utf-8") as handle:
        handle.write(json.dumps(record, ensure_ascii=False) + "\n")
    return {"written": 1, "decision_id": decision_id, "path": str(path)}


def _rewrite_jsonl_atomic(path, lines):
    """Atomically rewrite a JSONL file, truncating first.

    2026-10-04: the two teacher-log rewriters used
    `path.with_suffix(".tmp")` + `write_text()` + `replace()`. On Windows,
    if the new content is shorter and the handle reuses the same bytes, the
    stale tail survives as NUL padding -- the live s2_teacher_samples.jsonl
    ended up 18MB with 99.4% NUL. os.open(O_TRUNC) then write, fsync, replace.

    O_BINARY matters: without it the runtime translates \\n to \\r\\n, and every
    re-read of a completed teacher row then yields \\r inside the JSON string.
    """
    fd = os.open(str(path) + ".tmp",
                 os.O_WRONLY | os.O_CREAT | os.O_TRUNC | os.O_BINARY, 0o644)
    try:
        os.write(fd, ("\n".join(lines) + "\n").encode("utf-8"))
        os.fsync(fd)
    finally:
        os.close(fd)
    os.replace(str(path) + ".tmp", str(path))


def _s2_outcome_from_impact(score):
    """Map a measured action impact onto an S2 outcome class.

    2026-11-08: thresholds measured over 23,474 action_impact rows
    (median 0.20, p75 0.50, 12% <= 0). stage4 reads polarity: success keeps the
    teacher's confidence, partial floors it (0.55), failed floors harder.
    """
    try:
        s = float(score) if score is not None else 0.0
    except (TypeError, ValueError):
        s = 0.0
    if s >= 0.5:
        return "success"
    if s >= 0.2:
        return "partial"
    return "failed"


def _complete_s2_teacher_sample(decision_id, outcome, judge, reason):
    """Join only an explicitly identified measured outcome to teacher data."""
    if not decision_id:
        return {"updated": 0, "reason": "missing_decision_id"}
    updated = 0
    completed_item = None
    if not S2_TEACHER_LOG_PATH.exists():
        return {"updated": 0, "reason": "no_teacher_log"}
    with _S2_TEACHER_FILE_LOCK:
        lines = S2_TEACHER_LOG_PATH.read_text(encoding="utf-8", errors="replace").splitlines()
        for idx, raw in enumerate(lines):
            try:
                item = json.loads(raw)
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            if item.get("decision_id") != decision_id or item.get("status") == "completed":
                continue
            item["actual_outcome"] = {
                "outcome": str(outcome or "unknown")[:80],
                "judge": str(judge or "neutral")[:80],
                "reason": str(reason or "")[:500],
                "ts": time.strftime("%Y-%m-%d %H:%M:%S"),
            }
            item["status"] = "completed"
            lines[idx] = json.dumps(item, ensure_ascii=False)
            updated += 1
            completed_item = item
        if updated:
            _rewrite_jsonl_atomic(S2_TEACHER_LOG_PATH, lines)
    dataset = _append_s2_training_sample(completed_item) if completed_item else {"written": 0}
    return {"updated": updated, "decision_id": decision_id, "training_dataset": dataset}


_S2_LAST_EXPIRE_AT = 0.0


def expire_stale_s2_teacher_samples(max_age_s: int = 2400) -> dict:
    """Close never-answered teacher samples; pending then means in-flight only.

    2026-10-02 credit-loop: the bridge cannot report on decisions it never
    executed (stale drops, goal changes, give-ups), so those rows must age
    out here or the funnel counters stay unreadable forever. A late measured
    outcome still re-completes an expired row (only 'completed' is terminal).
    """
    path = S2_TEACHER_LOG_PATH
    if not path.exists():
        return {"expired": 0, "max_age_s": max_age_s}
    cutoff = time.time() - max_age_s
    expired = 0
    with _S2_TEACHER_FILE_LOCK:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
        for idx, raw in enumerate(lines):
            try:
                item = json.loads(raw)
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            if item.get("status") != "pending_outcome":
                continue
            try:
                ts = time.mktime(time.strptime(str(item.get("ts") or ""), "%Y-%m-%d %H:%M:%S"))
            except (ValueError, OverflowError):
                continue
            if ts >= cutoff:
                continue
            item["status"] = "expired"
            item["actual_outcome"] = {
                "outcome": "expired",
                "judge": "expired",
                "reason": f"no measured feedback within {max_age_s}s",
                "ts": time.strftime("%Y-%m-%d %H:%M:%S"),
            }
            lines[idx] = json.dumps(item, ensure_ascii=False)
            expired += 1
        if expired:
            _rewrite_jsonl_atomic(path, lines)
    if expired:
        print(f"[s2-expire] {expired} stale teacher samples -> expired", flush=True)
    return {"expired": expired, "max_age_s": max_age_s}


def _expire_s2_samples_throttled(min_gap_s: int = 600) -> None:
    """ponytail: one throttle; finer scheduling only if the log grows big."""
    global _S2_LAST_EXPIRE_AT
    now = time.time()
    if now - _S2_LAST_EXPIRE_AT < min_gap_s:
        return
    _S2_LAST_EXPIRE_AT = now
    try:
        expire_stale_s2_teacher_samples()
    except Exception as exc:  # never break the resting tick
        print(f"[s2-expire] skipped: {exc}", flush=True)


def _hydrate_s2_shadow_stats():
    """Restore shadow counters so the calibration window survives a reboot."""
    if not S2_SHADOW_LOG_PATH.exists():
        return
    try:
        for raw in S2_SHADOW_LOG_PATH.read_text(encoding="utf-8", errors="replace").splitlines():
            try:
                item = json.loads(raw)
                local = item.get("local", {})
                external = item.get("external", {})
                S2_SHADOW_STATS["samples"] += 1
                S2_SHADOW_STATS["matches"] += int(bool(item.get("matched")))
                S2_SHADOW_STATS["mismatches"] += int(not bool(item.get("matched")))
                S2_SHADOW_STATS["low_risk_samples"] += int(item.get("query_risk") == "low")
                S2_SHADOW_STATS["local_confidence_sum"] += float(local.get("confidence") or 0.0)
                S2_SHADOW_STATS["external_confidence_sum"] += float(external.get("confidence") or 0.0)
                S2_SHADOW_STATS["last_tick"] = item.get("tick")
                S2_SHADOW_STATS["last_sample_ts"] = item.get("ts")
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
    except OSError as exc:
        print(f"[s2-shadow] restore skipped: {exc}", flush=True)


_hydrate_s2_shadow_stats()

# ─── STDP params ───
A_PLUS = 0.005          # LTP rate
A_MINUS = 0.00525       # LTD rate (slightly stronger)
TAU = 20                # time constant
ETA_CHL = 0.001         # new edge init
PRUNE_THRESH = 0.001
SAVE_INTERVAL = 10      # persist every N queries

# ─── Concentration lock detection (anti-type-collapse) ───
CONCENTRATION_LOCK_COUNT = 0       # consecutive S1=S2 + conc >= 0.80
CONCENTRATION_LOCK_THRESHOLD = 3   # inject perturbation after this
PERTURBATION_SCALE = 0.15           # stddev of Gaussian noise on locked embedding

# ─── P3: Pulse Codec module-level globals ───
_PULSE_CODEC = None
_CODEC_FITTED = False


def init():
    """Full init: load grid -> full adjacency -> pre-compute."""
    global NEURONS, NEURON_EMBED, NEURON_TYPE, NEURON_TYPE_CONFIDENCE, NEURONS_MAP, EDGE_ACTIVE, NEURON_IDX, DRIFTER_SET, DRIFTER_RNG, COLD_STORE, _COLD_STORE, _PULSE_CODEC, _CODEC_FITTED
    t0 = time.time()
    _step_t0 = time.time()

    # 1. Init grid (loads SQLite + embeddings into memory)
    ng.init_grid(preload_partitions=False)
    print(f"[init-debug] Grid loaded: {len(ng._neuron_ids_list)} neurons, step={time.time()-_step_t0:.1f}s total={time.time()-t0:.1f}s", flush=True)

    # 2. Neuron data
    NEURONS = ng._neuron_ids_list  # avoid 10M string copy; mutations sync back at line ~1403

    # 閳光偓閳光偓 P3: Pulse Codec 閳�?load fitted 32d decoder 閳光偓閳光偓閳光偓閳光偓閳光偓閳光偓閳光偓閳光偓閳光偓閳光偓閳光偓閳光偓閳光偓閳光偓
    # Decode from 32d閳�?024d only on-demand during inference.
    _PULSE_CODEC = None
    _CODEC_FITTED = False
    _step_t0 = time.time()
    try:
        _PULSE_CODEC = pulse_codec.get_codec()
        if _PULSE_CODEC.is_fitted():
            _CODEC_FITTED = True
            _cs = _PULSE_CODEC.get_stats()
            print(f"[init-debug] Pulse codec loaded: {_cs['compressed_size_mb']:.1f}MB, step={time.time()-_step_t0:.1f}s total={time.time()-t0:.1f}s", flush=True)
        else:
            print("[init-debug] Pulse codec not fitted yet", flush=True)
    except Exception as _pc_err:
        print(f"[init-debug] Pulse codec load error: {_pc_err}", flush=True)

    # ── P6: ColdNeuronStore ────────────────────────────────────
    _COLD_STORE = None
    if _CODEC_FITTED:
        _step_t0 = time.time()
        try:
            _COLD_STORE = ColdNeuronStore(codec=_PULSE_CODEC)
            _COLD_STORE.populate_from_codec(_PULSE_CODEC)
            # P6-fix 2026-08-02: warm cache was never pre-warmed (hit_rate=0.0).
            # Pre-decode a working set so repeated cold access hits the LRU instead
            # of decode-per-access. warm_up() samples from populated cold codes.
            try:
                _warmed = _COLD_STORE.warm_up(target_size=20000)  # §2026-09-12: 2000→20000，与 WARM_CACHE_SIZE=50000 对齐，否则短世代永远追不上
                print(f"[init-debug] ColdNeuronStore warm_up: +{_warmed} warm-cache entries, step={time.time()-_step_t0:.1f}s total={time.time()-t0:.1f}s", flush=True)
            except Exception as _warm_err:
                print(f"[init-debug] ColdNeuronStore warm_up error: {_warm_err}", flush=True)
            print(f"[init-debug] ColdNeuronStore init: lazy mode + populate_from_codec, step={time.time()-_step_t0:.1f}s total={time.time()-t0:.1f}s", flush=True)
        except Exception as _p6_err:
            print(f"[init-debug] ColdNeuronStore init error: {_p6_err}", flush=True)
            _COLD_STORE = None

    # 閳光偓閳光偓 Drifter Neurons init閿涘湧0 妞嬪孩姣氱拋鈥冲灊閿涘�嗘敘閳光偓
    # P0-storm fix: 10M mode NEURON_EMBED.keys() proxies all 10M ids, but only
    # codec vocabulary (190K) has real embeddings. Sampling 5% of 10M = 500K
    # drifters, ~480K of which are empty shells, polluted STDP with unknown-type
    # edge updates. Pool is now limited to neurons with real codes (COLD_STORE
    # was populated from codec above, before this block).
    _drifter_pool = []
    if _COLD_STORE is not None and _COLD_STORE.size > 0:
        try:
            _drifter_pool = _COLD_STORE.all_neuron_ids()
        except Exception:
            _drifter_pool = []
    if not _drifter_pool:
        _drifter_pool = list(NEURON_EMBED._hot.keys())
    _drifter_n = max(1, int(len(_drifter_pool) * DRIFTER_FRACTION))
    DRIFTER_RNG = np.random.default_rng(seed=0xDEADBEEF)
    # Use index-based choice to avoid numpy converting large string lists to array
    _drifter_n = min(_drifter_n, len(_drifter_pool))
    _drifter_indices = DRIFTER_RNG.choice(len(_drifter_pool), size=_drifter_n, replace=False)
    DRIFTER_SET = {_drifter_pool[i] for i in _drifter_indices}
    print(f"[init-debug] Drifter set built: {len(DRIFTER_SET)} neurons (pool={len(_drifter_pool)}, 10M-safe), step={time.time()-_step_t0:.1f}s total={time.time()-t0:.1f}s", flush=True)

    # 閳光偓閳光偓 Neuron loop: hot閳�鎵�EURON_EMBED._hot, cold閳�鎵杘ldNeuronStore 閳光偓閳光偓
    _step_t0 = time.time()
    _hot = NEURON_EMBED._hot  # direct reference for speed
    _emb_rows = len(ng._embeddings_matrix) if ng._embeddings_matrix is not None else 0
    # 10M mode: only process HOT_THRESHOLD neurons; skip 10M dict builds for cold
    _neurons_count = min(HOT_THRESHOLD, len(NEURONS))
    for idx in range(_neurons_count):
        nid = NEURONS[idx]
        # 10M mode: _embeddings_matrix has only 2000 rows; codec handles the rest
        if idx < _emb_rows:
            emb = ng._embeddings_matrix[idx]
        elif _CODEC_FITTED and idx < HOT_THRESHOLD:
            # Decode hot neuron from pulse codec (get_compressed_code + decode_single)
            _c_code = _PULSE_CODEC.get_compressed_code(nid)
            if _c_code is not None:
                _n_type = nid.split("-")[1] if "-" in nid else "unknown"
                _emb_arr = _PULSE_CODEC.decode_single(_c_code, _n_type)
                emb = _emb_arr if _emb_arr is not None else ng._embeddings_matrix[idx % _emb_rows]
            else:
                emb = ng._embeddings_matrix[idx % _emb_rows]
        else:
            emb = None

        typ = NEURON_TYPE_OVERRIDES.get(nid, nid.split("-")[1] if "-" in nid else "meta")
        if typ in TYPE_NAMES:
            # P3: wrap type in role_scores dict
            NEURON_TYPE[nid] = {typ: 0.8} if isinstance(typ, str) else typ
        else:
            NEURON_TYPE[nid] = {"meta": 1.0}  # P3: single-role neuron  # was "unknown": unparsed IDs are meta/unknown, not functional noise
        NEURON_TYPE_CONFIDENCE.setdefault(nid, 0.0)

        # Cold-first: only first HOT_THRESHOLD go to hot dict
        if emb is not None:
            _hot[nid] = emb

    _step_t0 = time.time()
    if _COLD_STORE is not None:
        _hot_count = len(_hot)
        _cold_count = _COLD_STORE.size
        print(f"[init-debug] Neuron loop: hot={_hot_count}, cold={_cold_count}, step={time.time()-_step_t0:.1f}s total={time.time()-t0:.1f}s", flush=True)

    # ── Attach cold store to NEURON_EMBED proxy ────────────────
    if _COLD_STORE is not None:
        NEURON_EMBED.attach_cold_store(_COLD_STORE, NEURONS)
        COLD_STORE = _COLD_STORE
        # Release the full embeddings matrix early to free ~450MB
        try:
            ng._embeddings_matrix = None
            print("[p6] Released ng._embeddings_matrix (freed ~450MB)", flush=True)
        except Exception:
            pass

    # P3b: Background train 閳�?if codec not fitted, train async
    if not _CODEC_FITTED:
        def _bg_train_codec():
            try:
                time.sleep(3)  # let ng/neurons settle first
                _pc2 = pulse_codec.get_codec()
                if _pc2.is_fitted():
                    print("[pulse_codec] bg-train skip: already fitted", flush=True)
                    return
                _nids = list(NEURON_EMBED.keys())
                if len(_nids) < 1000:
                    print(f"[pulse_codec] bg-train skip: too few neurons ({len(_nids)})", flush=True)
                    return
                import numpy as _np
                _emb_mat = _np.zeros((len(_nids), 1024), dtype=_np.float32)
                for _i, _nid in enumerate(_nids):
                    _emb_mat[_i] = NEURON_EMBED[_nid]
                print(f"[pulse_codec] bg-train start: {len(_nids)} neurons", flush=True)
                _pc2.fit(_emb_mat, _nids, NEURON_TYPE)
                _pc2.save()
                print(f"[pulse_codec] bg-train done: {_pc2.get_stats()['compression_ratio']:.1f}x", flush=True)
                # Refresh cluster fit with new codes
                try:
                    _cm2 = cluster_manager.get_cluster_mgr()
                    _codes2 = _pc2.get_compressed_codes()
                    if _codes2 is not None:
                        _nids_all2 = list(NEURON_EMBED.keys())
                        _codec_nids2 = _pc2._neuron_ids or _nids_all2
                        _nid2idx2 = {nid: i for i, nid in enumerate(_nids_all2)}
                        _aligned2 = _np.zeros((len(_nids_all2), _codes2.shape[1]), dtype=_np.float32)
                        for _ci, _nid in enumerate(_codec_nids2):
                            _ei = _nid2idx2.get(_nid)
                            if _ei is not None:
                                _aligned2[_ei] = _codes2[_ci]
                        _cm2.fit(_aligned2, _nids_all2, tick=RESTING_STATE.get("tick", 0))
                        print("[cluster] bg-refit done after codec train", flush=True)
                except Exception as _cerr:
                    print(f"[cluster] bg-refit error: {_cerr}", flush=True)
            except Exception as _be:
                print(f"[pulse_codec] bg-train error: {_be}", flush=True)
        _train_thread = threading.Thread(target=_bg_train_codec, daemon=True)
        _train_thread.start()
        print("[pulse_codec] background train thread started", flush=True)

    # 2b. Seed dormant types: TYPE_NAMES with 0 neurons get DORMANT_SEED_N initial neurons
    # Each dormant type has 0 neurons -> IIT partition sees 0 active types -> Phi=0
    # This injection ensures all 19 TYPE_NAMES have at least a few neurons.
    _DORMANT_SEED_N = 5
    _new_neurons = []   # 閳�?always defined so P4 / 2c can reference it safely
    n_new = 0           # 閳�?same
    # P3: NEURON_TYPE values are role_scores dicts
    _used_types = set()
    # P3: extract role keys from role_scores dicts
    # P3: extract role keys from role_scores dicts
    for _v in NEURON_TYPE.values():
        if isinstance(_v, dict):
            _used_types.update(_v.keys())
        else:
            _used_types.add(str(_v))
    _dormant_types = [t for t in TYPE_NAMES if t not in _used_types]
    if _dormant_types:
        import json as _json
        import datetime as _dt
        _next_free_idx = len(NEURONS)
        _new_neurons = []
        with open(ng.NEURON_REGISTRY, 'a', encoding='utf-8') as _f:
            for _t in _dormant_types:
                for _i in range(_DORMANT_SEED_N):
                    _nid = f"n-{_t}-{_i:06d}"
                    _vec = np.random.randn(1024).astype(np.float32) * 0.01
                    _entry = {"id": _nid, "embedding": _vec.tolist(), "created": _dt.datetime.now().isoformat()}
                    _f.write(_json.dumps(_entry) + "\n")
                    NEURONS.append(_nid)
                    # P3: new neuron gets role_scores
                    NEURON_TYPE[_nid] = {_t: 0.8} if isinstance(_t, str) else _t
                    NEURON_EMBED[_nid] = _vec
                    NEURONS_MAP[_nid] = _vec
                    _new_neurons.append(_nid)
        ng._neuron_ids_list = list(NEURONS)
        n_new = len(_new_neurons)
        if n_new > 0:
            _new_emb = np.zeros((n_new, 1024), dtype=np.float32)
            for _j, _nid in enumerate(_new_neurons):
                _new_emb[_j] = NEURON_EMBED[_nid]
            ng._embeddings_matrix = np.vstack([ng._embeddings_matrix, _new_emb]) if ng._embeddings_matrix is not None else _new_emb
        ng._neuron_id_to_index = _IncrementalIndex(NEURONS)
        if hasattr(ng, '_index') and ng._index is not None and n_new > 0:
            try:
                if hasattr(ng._index, 'add'):
                    ng._index.add(_new_emb.astype(np.float32))
            except Exception as _faiss_err:
                print(f"[dormant] FAISS add failed (non-critical): {_faiss_err}", flush=True)
        print(f"[dormant] Seeded {n_new} neurons for types: {_dormant_types}", flush=True)

    # P4: Cluster Manager 閳�?fit k-means on Pulse Codec latent codes
    _CLUSTER_FIT_TICK = 0
    _CLUSTER_ALIGN_MAX = 500_000   # safety cap: skip alignment above this count (10M-mode)
    try:
        _cm = cluster_manager.get_cluster_mgr()
        _pc = pulse_codec.get_codec()
        if _pc.is_fitted() and _pc.get_compressed_codes() is not None:
            _codes = _pc.get_compressed_codes()
            # 10M-mode fix: NEURON_EMBED.keys() returns ALL 10M ids (cold proxy) which
            # always exceeds _CLUSTER_ALIGN_MAX, so cluster never fitted (enabled=false).
            # Correct scope: codec vocabulary (190K neurons that actually have codes).
            _codec_nids = _pc._neuron_ids or []
            if _codec_nids:
                _nids_all = list(_codec_nids)
                # Build reverse index: codec-row-idx -> neuron position in _nids_all
                _codec_nid_to_emb_idx = {nid: i for i, nid in enumerate(_nids_all)}
                _aligned_codes = np.zeros((len(_nids_all), _codes.shape[1]), dtype=np.float32)
                _matched = 0
                for ci, nid in enumerate(_codec_nids):
                    ei = _codec_nid_to_emb_idx.get(nid)
                    if ei is not None and ci < len(_codes):
                        _aligned_codes[ei] = _codes[ci]
                        _matched += 1
                print(f"[cluster] aligned {_matched}/{len(_nids_all)} neurons to codes", flush=True)
                _fit_result = _cm.fit(_aligned_codes, _nids_all, tick=RESTING_STATE.get("tick", 0))
                _CLUSTER_FIT_TICK = RESTING_STATE.get("tick", 0)
                print(f"[cluster] fitted: {_fit_result}", flush=True)
            else:
                print("[cluster] skip: codec vocab empty", flush=True)
        else:
            print("[cluster] skip: codec not fitted", flush=True)
    except Exception as _cl_err:
        print(f"[cluster] init skipped: {_cl_err}", flush=True)

    # P5 Fractal Attractor 閳�?init after cluster (both depend on TYPE_NAMES)
    try:
        fractal_attractor.init_fractal(TYPE_NAMES)
        print("[fractal] P5 FractalAttractorManager initialized", flush=True)
    except Exception as _fa_err:
        print(f"[fractal] init skipped: {_fa_err}", flush=True)
    finally:
        # 2c. Pre-wire edges for dormant neurons (accelerate IIT integration)
        #    Each dormant neuron gets 20 edges:
        #    10 -> top-10 most similar active neurons (by embedding cosine)
        #    10 -> random active neurons of complementary types
        if _new_neurons and ng._embeddings_matrix is not None and len(ng._embeddings_matrix) > n_new:
            import sqlite3 as _sqlite3
            import random as _random
            _random.seed(42)
            # Build active embedding matrix (exclude dormant neurons just added)
            _n_total = len(ng._embeddings_matrix)
            _n_active = _n_total - n_new
            _active_embs = ng._embeddings_matrix[:_n_active]  # first N_active rows are original
            _active_ids = list(ng._neuron_ids_list[:_n_active])
            _active_norm = _active_embs / (np.linalg.norm(_active_embs, axis=1, keepdims=True) + 1e-10)
            # Complementarity map: dormant_type -> list of complementary active types
            _COMPLEMENT = {
                "curiosity":  ["integrator", "doubt", "action", "memory"],
                "planning":   ["architect", "decider", "action", "integrator"],
                "social":     ["memory", "sensory", "action", "veto"],
                "ethical":    ["veto", "rule_modification", "doubt", "integrator"],
                "aesthetic":  ["sensory", "memory", "architect", "integrator"],
                "temporal":   ["memory", "integrator", "architect", "sensory"],
                "emotional":  ["veto", "action", "sensory", "doubt"],
                "spatial":    ["sensory", "memory", "action", "architect"],
                "cultural":   ["memory", "rule_modification", "veto", "decider"],
                "meta":       ["integrator", "architect", "doubt", "rule_modification"],
            }
            # Group active IDs by type (from existing NEURON_TYPE dict, not from the matrix)
            _active_by_type = {}
            _active_type_set = set()
            for _nid in _active_ids:
                _t = _get_primary_role(_nid, "unknown")
                if _t not in _active_by_type:
                    _active_by_type[_t] = []
                _active_by_type[_t].append(_nid)
                _active_type_set.add(_t)
            _now_ts = time.strftime("%Y-%m-%d %H:%M:%S")
            # Pre-wire each dormant neuron
            _edge_db = ng.GRID_EDGES_DB if hasattr(ng, 'GRID_EDGES_DB') and ng.GRID_EDGES_DB else None
            if _edge_db:
                _conn = _sqlite3.connect(str(_edge_db), timeout=10.0)
                _conn.execute("PRAGMA busy_timeout = 10000")
                _conn.execute("PRAGMA journal_mode = WAL")
                _prewire_count = 0
                for _nid in _new_neurons:
                    _t = _get_primary_role(_nid, "unknown")
                    _idx = ng._neuron_id_to_index.get(_nid)
                    if _idx is None:
                        continue
                    _emb = ng._embeddings_matrix[_idx]
                    _emb_norm = _emb / (np.linalg.norm(_emb) + 1e-10)
                    # Part A: 10 edges to top-10 similar active neurons
                    _sims = _active_norm @ _emb_norm  # (N_active,)
                    _top_k = min(10, len(_active_ids))
                    _top_idx = np.argpartition(-_sims, _top_k)[:_top_k]
                    for _i in _top_idx:
                        _target = _active_ids[_i]
                        _w = max(0.3, min(1.0, float(_sims[_i])))
                        _conn.execute("INSERT OR REPLACE INTO edges (src, dst, weight, last_update) VALUES (?,?,?,?)",
                                      (_nid, _target, round(_w, 4), _now_ts))
                        _prewire_count += 1
                    # Part B: 10 edges to random complementary active neurons
                    _comp = _COMPLEMENT.get(_t, ["integrator", "memory", "sensory", "architect"])
                    _comp_candidates = []
                    for _ct in _comp:
                        _comp_candidates.extend(_active_by_type.get(_ct, []))
                    if len(_comp_candidates) < 10:
                        _comp_candidates = _active_ids
                    _selected = _random.sample(_comp_candidates, min(10, len(_comp_candidates)))
                    for _target in _selected:
                        _w = round(_random.uniform(0.3, 0.8), 4)
                        _conn.execute("INSERT OR REPLACE INTO edges (src, dst, weight, last_update) VALUES (?,?,?,?)",
                                      (_nid, _target, _w, _now_ts))
                        _prewire_count += 1
                    # Part C: Reverse edges - connect active back TO dormant
                    # This feeds activation INTO the dormant neurons
                    for _i in _top_idx:
                        _target = _active_ids[_i]
                        _w = max(0.3, min(1.0, float(_sims[_i])))
                        _conn.execute("INSERT OR REPLACE INTO edges (src, dst, weight, last_update) VALUES (?,?,?,?)",
                                      (_target, _nid, _w, _now_ts))
                        _prewire_count += 1
                _conn.commit()
                _conn.close()
                print(f"[dormant] Pre-wired {_prewire_count} edges for {len(_new_neurons)} dormant neurons", flush=True)
            else:
                print(f"[dormant] WARNING: GRID_EDGES_DB not set, skipping pre-wire", flush=True)


    # 3. EDGE_ACTIVE: lazy-loaded on first access per neuron (avoid OOM on init)
    global _edge_store_singleton, _lazy_edge_lock
    _edge_store_singleton = None
    _lazy_edge_lock = None
    import threading as _th
    _lazy_edge_lock = _th.RLock()
    print(f"    [init] EDGE_ACTIVE deferred (lazy-load on first query access)", flush=True)

    # 3b. EdgeStore v2: Active/Cold two-tier (P1 妞嬪孩姣氱拋鈥冲灊)
    global EDGE_STORE_V2
    edge_store_v2.set_workspace(WORKSPACE)
    EDGE_STORE_V2 = edge_store_v2.get_edge_store_v2(WORKSPACE)
    edge_store_v2.set_edge_active_ref(EDGE_ACTIVE)
    _edge_id_prefixes = {
        f"n-{neuron_type}-"
        for neuron_type in TYPE_NAMES
        if neuron_type and neuron_type != "unknown"
    }
    EDGE_STORE_V2.set_compatible_id_prefixes(_edge_id_prefixes)
    print(f"    [edge_store_v2] init OK 閳�?Active: {len(EDGE_ACTIVE)} sources, Cold: unloaded", flush=True)

    # P6: Cold tier warmup 閳�?proactively demote LRU active sources to cold at init
    # so that cold tier has content for future cold-start scenarios.
    if EDGE_STORE_V2 is not None and len(EDGE_ACTIVE) > 0:
        try:
            _warm = min(50, len(EDGE_ACTIVE) // 2)
            _demoted = EDGE_STORE_V2.downgrade_lru(_warm)
            print(f"    [edge_store_v2] cold warmup: demoted {_demoted} LRU sources to cold tier", flush=True)
        except Exception as _cw_err:
            print(f"    [edge_store_v2] cold warmup skipped: {_cw_err}", flush=True)

    # P2 閸斻劍鈧�浣衡枅閻ゅ繑瀚囬幍? 濞夈劌鍙嗛崗銊ョ湰瀵�鏇犳暏
    edge_sparsifier.set_refs(edge_active=EDGE_ACTIVE, neuron_type=NEURON_TYPE, edge_store_v2=EDGE_STORE_V2)
    # 2026-09-11 refactor made coactivation_update() grow edges SYNCHRONOUSLY
    # (the async offload + _grow_queue + start_grow_worker are all gone from
    # edge_sparsifier.py). The start_grow_worker() call left behind by that
    # refactor has raised AttributeError on every boot since — it was only
    # visible in the traceback, not in /status, and growth/pruning kept working
    # through the direct path. Nothing to start; do not reintroduce the worker.
    print(f"    [edge_sparsifier] init OK - coactivation_threshold={edge_sparsifier.COACTIVATION_THRESHOLD}, expiry={edge_sparsifier.EDGE_EXPIRY_DAYS}d", flush=True)

    # 4. NEURONS_MAP (needed by AttractorNetwork) - 10M mode: only build for hot neurons
    for nid in list(_hot.keys()):
        NEURONS_MAP[nid] = _hot[nid]
    print(f"    [init] NEURONS_MAP built: {len(NEURONS_MAP)} neurons (hot only, 10M cold via lazy)", flush=True)

    # 4.5 NEURON_IDX for embedding feedback
    global NEURON_IDX
    NEURON_IDX = ng._neuron_id_to_index
    print(f"    [init] NEURON_IDX ready (lazy, ~{min(HOT_THRESHOLD, len(NEURONS))} hot neurons)", flush=True)

    # 6. Resting state seeds 閳�?10M mode: only sample from hot neurons
    for t in TYPE_NAMES:
        typed = _filter_by_role(NEURON_TYPE, t)
        RESTING_STATE["last_seeds"].extend(random.sample(typed, min(5, len(typed))))
    print(f"    [init] Resting seeds: {len(RESTING_STATE['last_seeds'])} (hot only)", flush=True)


# ─── Memory Search (direct SQLite, zero LLM dependency) ───
# 2026-08-08 fix: was WORKSPACE.parent / "memory" / "memu.db" which does not exist.
# Use workspace-local memory/ so _memory_search can actually hit the DB.
MEMORY_DB = WORKSPACE / "memory" / "memu.db"



# ─── Lazy Edge Loading (avoid OOM at init) ────────────────────────────────
_edge_store_singleton = None
_lazy_edge_lock = None

def _get_edge_store():
    """Thread-safe singleton EdgeStore."""
    global _edge_store_singleton
    if _edge_store_singleton is None:
        _edge_store_singleton = ng.EdgeStore()
    return _edge_store_singleton

def _get_edges_lazy(nid: str) -> list:
    """Load edges for a single neuron.
    FIX: Prioritize EDGE_ACTIVE to avoid cold tier compatibility issues.
    """
    # Fast path: already in EDGE_ACTIVE
    if nid in EDGE_ACTIVE:
        return EDGE_ACTIVE[nid]

    # Route through EdgeStoreV2 (cold tier aware) - only if not in EDGE_ACTIVE
    if EDGE_STORE_V2 is not None:
        try:
            edges = EDGE_STORE_V2.get_edges(nid)
            if edges is not None:
                # Sync EDGE_ACTIVE for backward-compatible direct-access code paths
                _edge_active_set(nid, edges)
                return edges
        except Exception as e:
            print(f"[warn] _get_edges_lazy EDGE_STORE_V2 error for {nid}: {e}", flush=True)
        return []

    # Fallback: direct EdgeStore (no cold tier)
    try:
        store = _get_edge_store()
        data = store.get_outgoing_edges(nid)
        if data:
            outgoing = [(dst, float(w)) for dst, w in data if w > 0.001]
            with _lazy_edge_lock:
                _edge_active_set(nid, outgoing)
        else:
            with _lazy_edge_lock:
                _edge_active_set(nid, [])
    except Exception:
        with _lazy_edge_lock:
            _edge_active_set(nid, [])
    return EDGE_ACTIVE.get(nid, [])

def _ensure_edges_batch(nids: list) -> None:
    """Pre-load edges for a batch of neuron IDs via EdgeStoreV2."""
    if EDGE_STORE_V2 is not None:
        batch = EDGE_STORE_V2.get_edges_bulk(nids)
        # Keep the legacy cache consistent with the single-source lazy path.
        with _lazy_edge_lock:
            for src, edges in batch.items():
                _edge_active_set(src, edges)
        return
    missing = [n for n in nids if n not in EDGE_ACTIVE]
    if not missing:
        return
    try:
        store = _get_edge_store()
        batch_data = store.batch_all_edges(missing)
        with _lazy_edge_lock:
            for src, data in batch_data.items():
                outgoing = [(dst, float(w)) for dst, w in data.get("out", []) if w > 0.001]
                if outgoing:
                    _edge_active_set(src, outgoing)
                else:
                    _edge_active_set(src, [])
    except Exception:
        with _lazy_edge_lock:
            for n in missing:
                _edge_active_set(n, [])


def _attractor_step_safe(attractor, q, init_acts, neurons_map, adj,
                         propagation_rounds=3, top_k=50, **cpu_kw):
    """2026-11-03: CUDA OOM 不该打死整个 job。

    GPU 只有 16GiB, 和桌面/bge/ComfyUI 共用。实测在 "14.18 GiB is free"、PyTorch
    只占 621 MiB 时仍会因 Windows 进程 VRAM 预算/碎片 OOM (tried to allocate
    120 MiB) —— 这不是"显存不够", 所以缩配置没用。GPU 快但不可靠, 因此 OOM 时降级
    到 CPU 重跑一次 (两边已有 test_gpu_cpu_parity.py 差分保证语义一致), 只慢不坏。
    cpu_kw 透传调用点的抑制/泄漏参数, 避免降级时语义跑偏。
    返回 (结果, 实际使用的 attractor) —— history 必须取实际那个。
    """
    try:
        return attractor.step(q, init_acts, neurons_map, adj), attractor
    except Exception as _e:
        if "out of memory" not in str(_e).lower():
            raise
        print(f"[kwta-gpu] step OOM -> CPU fallback: {str(_e)[:120]}", flush=True)
        try:
            import torch as _torch
            _torch.cuda.empty_cache()
        except Exception:
            pass
        _cpu = ng.AttractorNetwork(propagation_rounds=propagation_rounds, top_k=top_k,
                                   **cpu_kw)
        return _cpu.step(q, init_acts, neurons_map, adj), _cpu


def _memory_search(query: str, limit: int = 5) -> str:
    """Query agent-memory SQLite directly. Returns formatted context string.
    No LLM, no network call, pure local SQLite. Gracefully returns '' on failure."""
    try:
        if not MEMORY_DB.exists():
            return ""
        import sqlite3 as _sqlite3
        conn = _sqlite3.connect(str(MEMORY_DB))
        conn.row_factory = _sqlite3.Row
        cur = conn.cursor()
        # Tokenize: whitespace split for English, character bigrams for CJK.
        # This keeps DB rows like "IDENTITY_TENSION" / "L5 action" discoverable
        # even when the user asks in Chinese ("identity鐨勫唴瀹�").
        _CJK_RE = None
        try:
            import re as _re
            _CJK_RE = _re.compile(r"[\u4e00-\u9fff\u3400-\u4dbf\uf900-\ufaff\u3040-\u30ff\uac00-\ud7af]")
        except Exception:
            pass

        def _split_cjk_ascii(s: str):
            # Split a token into sub-tokens at CJK/ASCII boundaries so
            # "identity鐨勫唴瀹�" -> ["identity", "鐨勫唴瀹�"]
            parts = []
            buf = ""
            for ch in s:
                if ch.isspace():
                    if buf:
                        parts.append(buf)
                        buf = ""
                    continue
                if buf and _CJK_RE and ((_CJK_RE.search(buf[-1]) is not None) != (_CJK_RE.search(ch) is not None)):
                    parts.append(buf)
                    buf = ch
                else:
                    buf += ch
            if buf:
                parts.append(buf)
            return parts

        raw_tokens = query.strip().split()
        token_set = set()
        for tok in raw_tokens:
            tok = tok.strip(""".,!?;:'"<>()[]{}/\\|`~@#$%^&*+-=_""")
            if not tok:
                continue
            for sub in _split_cjk_ascii(tok):
                sub = sub.strip()
                if not sub:
                    continue
                if _CJK_RE and _CJK_RE.search(sub):
                    # CJK path: keep the whole word, plus character bigrams/trigrams
                    if 2 <= len(sub) <= 12:
                        token_set.add(sub)
                    for i in range(len(sub) - 1):
                        token_set.add(sub[i:i+2])
                    for i in range(len(sub) - 2):
                        token_set.add(sub[i:i+3])
                else:
                    # ASCII/English path: keep the word as-is
                    if len(sub) >= 2:
                        token_set.add(sub)
                    if len(sub) > 2:
                        for i in range(len(sub) - 1):
                            gram = sub[i:i+2]
                            if gram.isascii():
                                token_set.add(gram)
        # 2026-09-19: OR 子句 ≥1000 会超 SQLite 表达式深度(max 1000) → 整条检索
        # 被 except 静默吞成 ""(MC 决策提示词 3099 字 = 1540 tokens 必炸)。截断够用。
        tokens = [t for t in token_set if len(t) >= 2][:400]
        if not tokens:
            return ""
        clauses = []
        params = []
        for tok in tokens:
            p = f"%{tok}%"
            clauses.append("(summary LIKE ? OR content LIKE ?)")
            params.extend([p, p])
        where_sql = " OR ".join(clauses)
        params.append(limit)
        cur.execute(
            f"SELECT id AS rowid, summary, content, memory_type, confidence, recalls, ts "
            f"FROM memory_items WHERE {where_sql} "
            "ORDER BY (salience * 0.4 + confidence * 10 + MIN(recalls, 50) * 0.1 "
            "+ (ts - strftime('%s','now')) / 86400.0 * 24) DESC, rowid DESC "
            "LIMIT ?",
            params
        )
        rows = cur.fetchall()
        # 2026-08-15 fix: 检索命中递增 recalls（热度信号），同分时 rowid DESC 让新记忆优先
        if rows:
            try:
                cur.execute(
                    "UPDATE memory_items SET recalls = recalls + 1 WHERE rowid IN (%s)"
                    % ",".join("?" * len(rows)),
                    tuple(r["rowid"] for r in rows),
                )
                conn.commit()
            except Exception:
                pass
        conn.close()
        if not rows:
            # CJK queries generate Chinese tokens that cannot match English
            # summaries. Fall back to recent salient records so queries like
            # "鏈�杩戝湪鍋氫粈涔�" still surface concrete past actions.
            try:
                conn2 = _sqlite3.connect(str(MEMORY_DB))
                conn2.row_factory = _sqlite3.Row
                cur2 = conn2.cursor()
                rows = cur2.execute(
                    "SELECT summary, content, memory_type, confidence, recalls, ts "
                    "FROM memory_items "
                    "ORDER BY (salience * 0.4 + confidence * 10 + MIN(recalls, 50) * 0.1 "
                    "+ (ts - strftime('%s','now')) / 86400.0 * 24) DESC, rowid DESC "
                    "LIMIT ?",
                    (limit,)
                ).fetchall()
                conn2.close()
            except Exception:
                return ""
            if not rows:
                return ""
            parts = []
            for r in rows:
                text = r["summary"] or r["content"] or ""
                # 2026-08-15 fix(B): 第一人称感官记忆标注，供 ego 区分并认领自身体验
                tag = "第一人称" if r["memory_type"] == "sensory" else ""
                parts.append(f"  [{r['memory_type']}|{tag}|conf={r['confidence']}|recalls={r['recalls']}] {text[:200]}")
            return "[Recent Activity (fallback)]\n" + "\n".join(parts)
        parts = []
        for r in rows:
            text = r["summary"] or r["content"] or ""
            # 2026-08-15 fix(B): 第一人称感官记忆标注，供 ego 区分并认领自身体验
            tag = "第一人称" if r["memory_type"] == "sensory" else ""
            parts.append(f"  [{r['memory_type']}|{tag}|conf={r['confidence']}|recalls={r['recalls']}] {text[:200]}")
        return "[Past Experience]\n" + "\n".join(parts)
    except Exception as _mse:
        # 2026-09-19: 以前这里裸 except 吞掉一切(含 "Expression tree is too large"),
        # 检索静默变空。留一行签名, 别再无声失败。
        print(f"[memory-search] failed: {type(_mse).__name__}: {_mse}", flush=True)
        return ""


def web_search_tavily(query: str, max_results: int = 5, search_depth: str = "basic") -> dict:
    """Search the web via Tavily API. Returns structured results.

    This gives TL-Ego real external information access, complementing
    the local memory search. Calls the existing tavily_search.py script
    via subprocess to avoid adding new dependencies to the server process.

    Args:
        query: search query string
        max_results: number of results to return (default 5)
        search_depth: 'basic' (fast, 1-2s) or 'advanced' (comprehensive, 5-10s)

    Returns:
        dict with keys: success, answer, results, error
    """
    try:
        from l7_action_interface import web_search as _l7_web_search
        found = _l7_web_search(query, max_results=max_results)
        rows = ((found.get("data") or {}).get("results") or []) if found.get("status") == "ok" else []
        if rows:
            return {
                "success": True,
                "answer": "",
                "results": rows[:max_results],
                "error": "",
                "backend": (found.get("data") or {}).get("backend", "stepsearch_mcp"),
            }
    except Exception as _step_err:
        print(f"[web_search] stepsearch failed: {type(_step_err).__name__}: {_step_err}", flush=True)

    try:
        script_path = WORKSPACE.parent / "skills" / "tavily" / "scripts" / "tavily_search.py"
        if not script_path.exists():
            return {"success": False, "error": f"tavily script not found: {script_path}", "answer": "", "results": []}
        cmd = [
            sys.executable, str(script_path),
            query,
            "--max-results", str(max_results),
            "--depth", search_depth,
            "--json",
        ]
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=30, cwd=str(script_path.parent),
                              encoding="utf-8", errors="replace")
        if proc.returncode != 0:
            err = proc.stderr.strip() or proc.stdout.strip()
            return {"success": False, "error": f"tavily exit {proc.returncode}: {err[:300]}", "answer": "", "results": []}
        out = proc.stdout.strip()
        # Try to parse JSON from the script output
        # The script may wrap JSON in a header line like "results:" or similar
        json_start = out.find('{')
        if json_start < 0:
            return {"success": False, "error": f"no JSON in tavily output: {out[:300]}", "answer": "", "results": []}
        data = json.loads(out[json_start:])
        # 2026-10-11: a script-level error dict (missing API key etc.) used to
        # fall through as success:true with 0 results — the web_explore loop
        # then recorded "stored evidence" for nothing. Surface it instead.
        if isinstance(data, dict) and data.get("error"):
            return {"success": False, "error": str(data.get("error"))[:300], "answer": "", "results": []}
        if not (data.get("results") or []):
            return {"success": False, "error": "tavily returned no results", "answer": "", "results": []}
        answer = data.get("answer", "") or ""
        raw_results = data.get("results", []) or []
        results = []
        for item in raw_results[:max_results]:
            results.append({
                "title": item.get("title", ""),
                "url": item.get("url", ""),
                "content": (item.get("content", "") or "")[:500],
                "score": item.get("score", 0.0),
            })
        return {"success": True, "answer": answer, "results": results, "error": ""}
    except subprocess.TimeoutExpired:
        return {"success": False, "error": "tavily search timed out", "answer": "", "results": []}
    except Exception as e:
        return {"success": False, "error": str(e), "answer": "", "results": []}



def get_embedding(text: str) -> list:
    # 2026-10-13 实测: 8002 旧参数 --batch-size 512 → llama.cpp embeddings 端点对单条 input 硬上限
    # = 物理 batch size, 超了直接 500 "input (N tokens) is too large to process"。
    # MC 决策 query(重 CJK ~1.7 token/字符) 858 字符就 513 tokens → 每轮必炸 → full_pipeline skip → 桥空转。
    # 已在 bge8002.cmd 把 batch/ubatch 提到 4096 根治(单条上限 ~4096 tokens); 这里保留 3000 字符
    # 上限防的是 GGUF compute-error 长尾(实测 cjk >3547 字符仍 500), 与 8002 现状无关, 是兜底。
    safe_text = text[:3000] if len(text) > 3000 else text
    try:
        r = requests.post(BGE_URL, json={"input": safe_text, "model": "default"}, timeout=30, proxies={"http": None, "https": None})
        return r.json()["data"][0]["embedding"]
    except Exception as _e:
        print(f"[embedding] service unavailable ({_e}), returning None", flush=True)
        return None


