def _read_metacontemplate_runs() -> int:
    """Read persistent metacontemplate_runs from self-model file."""
    try:
        model_path = WORKSPACE / ".lae" / "lae_self_model.json"
        if model_path.exists():
            with open(model_path, "r", encoding="utf-8") as f:
                model = json.load(f)
            return model.get("metacontemplate_runs", 0)
    except Exception:
        pass
    return METACONTEMPLATE_COUNT  # fallback to in-memory


def _read_last_meta_insight() -> dict:
    """Read the most recent metacontemplate meta_insight from self-model file.

    2026-08-13: meta_insight persistence added (previously discarded). This is
    the read side so the self-model manifest / introspection layer can consume
    cognitive_stability, trial_consistency, seed_health etc.
    """
    try:
        model_path = WORKSPACE / ".lae" / "lae_self_model.json"
        if model_path.exists():
            with open(model_path, "r", encoding="utf-8") as f:
                model = json.load(f)
            return model.get("last_meta_insight") or {}
    except Exception:
        pass
    return {}


_ROTATE_NEXT_CHECK: dict = {}


def _rotate_jsonl(path, max_bytes: int = 50_000_000):
    """Roll an append-only JSONL log to <name>.old once it exceeds max_bytes.

    2026-08-13: several JSONL logs grew unbounded (ego_consumption 574MB,
    live_affordance_snapshots 88MB, ...). Call before every append site.
    """
    try:
        # 2026-09-11: 这个检查挂在每个 append 站点上, 热路径(每 tick/每次快照)白跑
        # 两次系统调用 (py-spy: metacontemplate 线程 38% 在 pathlib.stat)。日志膨胀
        # 是分钟级的事, 60s 查一次足够。
        _now = time.time()
        if _ROTATE_NEXT_CHECK.get(str(path), 0) > _now:
            return
        _ROTATE_NEXT_CHECK[str(path)] = _now + 60
        if path.exists() and path.stat().st_size > max_bytes:
            path.replace(path.with_name(path.name + ".old"))
    except Exception:
        pass


