NOISE_MODES = ["white", "pink", "sparse", "none"]

def _generate_noise(shape, mode, noise_amp, pink_state=None):
    """Generate noise vector per mode.
    - white:  Gaussian N(0, amp)
    - pink:   1/f approximation (persistent Brownian drift)
    - sparse: random 30% of dimensions, scaled by amp x 2
    - none:   zero vector
    Returns (noise_vec, updated_pink_state).
    """
    d = shape[0]
    if mode == "white":
        return np.random.normal(0, noise_amp, shape), pink_state
    elif mode == "pink":
        # Persistent drift: accumulate small steps, apply 1/f decay
        step = np.random.normal(0, noise_amp * 0.4, shape)
        if pink_state is None:
            pink_state = np.zeros(shape)
        pink_state = pink_state * RESTING_STATE["pink_alpha"] + step
        return pink_state.copy(), pink_state
    elif mode == "sparse":
        noise = np.zeros(shape)
        n_sparse = max(1, int(d * 0.30))
        idxs = np.random.choice(d, n_sparse, replace=False)
        noise[idxs] = np.random.normal(0, noise_amp * 1.8, n_sparse)
        return noise, pink_state
    else:  # "none"
        return np.zeros(shape), pink_state


def _apply_integrator_concentration_floor(type_activation: dict, floor) -> bool:
    """Raise integrator's raw activation share to an explicit policy floor.

    The compensated type_activation is what feeds dominant selection and the
    reported concentration, so this is a real behavioural lever, not telemetry.
    Default floor=0 is a no-op. The floor caps at 0.5 in PARAM_RANGES so the
    integrator cannot take the whole workspace.
    """
    try:
        floor = float(floor or 0.0)
    except (TypeError, ValueError):
        return False
    if not (0.0 < floor < 1.0) or not type_activation:
        return False
    try:
        total = sum(float(v) for v in type_activation.values() if float(v) > 0)
        integ = max(0.0, float(type_activation.get("integrator", 0.0) or 0.0))
    except (TypeError, ValueError):
        return False
    if total <= 0:
        return False
    share = integ / total
    if share >= floor:
        return False
    # Add delta so that (integ + delta) / (total + delta) == floor.
    delta = total * (floor - share) / (1.0 - floor)
    if delta <= 0:
        return False
    type_activation["integrator"] = integ + delta
    return True


def _apply_type_dominance_cap(type_activation: dict, cap) -> bool:
    """Clip any single type's raw activation share to an explicit ceiling.

    Homeostatic twin of _apply_integrator_concentration_floor: the floor only
    lifts a starving type, nothing stops a hoarding one. Measured this session
    (tick 60776): integrator holds resting_dominant with resting_concentration
    0.1063 while competition stays 0.9573. Default cap=0 is a no-op. Clipped
    mass is NOT redistributed (total shrinks, starved types' shares rise) --
    that is what breaks the monopoly. Basis: heterosynaptic/homeostatic
    competition stabilizes WTA dynamics (fncom.2014.00068): the winner needs
    inhibitory pressure, not just excitation of the losers.
    """
    try:
        cap = float(cap or 0.0)
    except (TypeError, ValueError):
        return False
    if not (0.0 < cap < 1.0) or not type_activation:
        return False
    try:
        total = sum(float(v) for v in type_activation.values() if float(v) > 0)
    except (TypeError, ValueError):
        return False
    if total <= 0:
        return False
    clipped = False
    for _t in list(type_activation.keys()):
        try:
            _v = float(type_activation.get(_t, 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        if _v <= 0 or _v / total <= cap:
            continue
        # same algebra as the floor's delta: x / (total - v + x) == cap
        # ponytail: single pass against the pre-clip total; if 2+ types
        # exceed the cap the post-clip shares tighten further next tick.
        type_activation[_t] = cap * (total - _v) / (1.0 - cap)
        clipped = True
    return clipped


