    # Offline 20-tick sim: hard mean 1.0 閳�?soft mean 0.57 (-43%).
    def _soft_type_surprise(pred, actual):
        if pred == actual:
            return 0.0
        _family = {
            "integrator": "meta", "architect": "meta", "rule_modification": "meta",
            "planner": "meta",
            "doubt": "control", "veto": "control", "decider": "control",
            "action": "exec", "memory": "exec",
            "sensory": "input",
        }
        _siblings = {
            frozenset({"integrator", "architect"}),
            frozenset({"architect", "rule_modification"}),
            frozenset({"integrator", "rule_modification"}),
            frozenset({"doubt", "veto"}),
            frozenset({"doubt", "decider"}),
            frozenset({"veto", "decider"}),
            frozenset({"action", "memory"}),
        }
        if frozenset({pred, actual}) in _siblings:
            return 0.35
        fa, fb = _family.get(pred), _family.get(actual)
        if fa and fb and fa == fb:
            return 0.55
        if fa and fb and frozenset({fa, fb}) == frozenset({"meta", "control"}):
            return 0.75
        return 1.0

