def _kw_hit(keyword: str, text_lower: str) -> bool:
    """关键词边界匹配: 关键词前面必须是词首(非字母/数字/下划线), 后缀保持贪心。

    explor→exploration ✓, calibrat→calibrated ✓, read→already ✗, block→unblocked ✗。
    词源问题(comm→commander 这种"词首真命中但语义偏")边界匹配管不了, 那是 hint 词源的事。
    """
    return re.search(r"(?<![a-z0-9_])" + re.escape(keyword), text_lower) is not None


def _recent_dispatch_types(limit: int = 12) -> list:
    """l5_action 车道最近派发的 goal_type 列表 —— 读 .lae/l5_dispatch_requests.jsonl 尾部。

    **别改用 .lae/l5_trigger_queue.jsonl** —— 那是"novel kind 待办队列", 只收 need_*/custom_*,
    拿它算占比会把派发构成算成 100% grown (2026-10-16 实测踩雷: 队列口径 222/222 全是 grown,
    真记录 l5_action 车道生命周期 grown 只占 5%, 近 60 次 51%)。comm_action 是另一条车道, 不计入。
    只读尾 256KB, 无新增状态。
    """
    try:
        _q = WORKSPACE / ".lae" / "l5_dispatch_requests.jsonl"
        with open(_q, "rb") as _f:
            _f.seek(0, 2)
            _size = _f.tell()
            _truncated = _size > 262144
            _f.seek(max(0, _size - 262144))
            _tail = _f.read().decode("utf-8", errors="replace")
        _lines = _tail.splitlines()
        if _truncated:
            _lines = _lines[1:]      # 被截断时首行是半条, 丢弃
        _out = []
        for _line in _lines:
            _line = _line.strip()
            if not _line:
                continue
            try:
                _d = json.loads(_line)
            except Exception:
                continue
            if _d.get("type") == "l5_action":
                _out.append(str(_d.get("goalType") or ""))
        return _out[-limit:]
    except Exception:
        return []


# 2026-11-04 (l5g-20261104-065568): per-goalType dispatch cooldown for STATIC types.
# 实测: 最近 300 条 l5_action 有 18 对连续同 goalType (静态 9: knowledge_upgrade x5,
# memory_recall x2, decider_deliberate, action_execute; grown 9 走 task_kind_growth 冷却)。
# l5_action 行自带 UTC ISO timestamp -> goalType->last_dispatch_ts 直接从派发日志尾部推导,
# 与 _recent_dispatch_types 同一口径, 不需要 warden 侧新增状态 (warden 的 saveState 是全量
# 覆写, 手改的 map 会被在内存里的旧 state 冲掉; 且插件文件不在 repair 白名单)。
_TYPE_COOLDOWN_SEC = 7200  # 2h: 实测派发间隔 8-40min, 静态类型间隔中位数 1.9h


def _last_dispatch_ts_by_type() -> dict:
    """goalType -> 最近一条 l5_action 的 epoch 秒 (256KB 尾部; 行序即时间序, 后行覆盖)。"""
    try:
        _q = WORKSPACE / ".lae" / "l5_dispatch_requests.jsonl"
        with open(_q, "rb") as _f:
            _f.seek(0, 2)
            _size = _f.tell()
            _f.seek(max(0, _size - 262144))
            _tail = _f.read().decode("utf-8", errors="replace")
        _lines = _tail.splitlines()
        if _size > 262144:
            _lines = _lines[1:]      # 被截断时首行是半条, 丢弃
        _out = {}
        for _line in _lines:
            try:
                _d = json.loads(_line)
            except Exception:
                continue
            if _d.get("type") != "l5_action" or not _d.get("goalType") or not _d.get("timestamp"):
                continue
            try:
                _ep = datetime.fromisoformat(str(_d.get("timestamp")).replace("Z", "+00:00")).timestamp()
            except Exception:
                continue
            _out[str(_d["goalType"])] = _ep
        return _out
    except Exception:
        return {}


