def _incumbent_penalty_scale() -> float:
    """选择器现任惩罚倍率（2026-11-11）。1.0 = 原 -0.10，完全等价旧行为。

    加这个读点的原因不是"多一个旋钮"，而是两条 L5 目标拒写族行时给的数据：
    action 0.2053 / architect 0.2037 按 avg_conc 已排 3/4 却 dom_rate=0.0 ——
    它们死在选择器的算术上（现任惩罚 -0.10 对 Branch-2 最高 +0.80），11 个旧键
    没有一个能到这一层，所以"造新族"在这层根本没有落地点。
    读点自己钳在 PARAM_RANGES 内：runtime_params.json 可能被手改/回滚成离谱值，
    惩罚过头会把 incumbent 永久踢出 —— 那只是换一种锁死。
    """
    try:
        raw = RESTING_STATE.get("incumbent_penalty_scale", 1.0)
        s = 1.0 if raw is None else float(raw)
    except (TypeError, ValueError):
        return 1.0
    return max(0.5, min(12.0, s))


# ── L5 参数写权持有 (2026-11-07) ────────────────────────────────────────────
# 实测 11-07: kwta_pool_mult 全天被写 21 次, 其中 20 次是 L10
# kwta_threshold_expansion 强行写回 3.0 —— L5 10:21:48 落地的 5.0 在 11:27:03 被
# 覆盖, 之后每次 boot_replay 又从快照读回 3.0。任何 L5 落地都活不过一小时, 事后
# 回读永远看不到它自己的效果。这是"空落地"的机制根因, 补后验回读治不了。
# 规则: l5g-* 写入后 L5_PARAM_HOLD_S 秒内, 只有 l5g-/operator/user/hermes/ttl 能改这个键。
L5_PARAM_HOLD_S = float(os.environ.get("EGO_L5_PARAM_HOLD_S", "5400"))
_L5_PARAM_HOLD = {}  # key -> [until_ts, value, source]; 另有 "_seeded" 标记


def _l5_hold_seed():
    """从审计账本恢复未过期的持有 —— 每天 3 次重启不该让保护失效。"""
    if _L5_PARAM_HOLD.get("_seeded"):
        return
    _L5_PARAM_HOLD["_seeded"] = True
    try:
        now = time.time()
        for _line in open(WORKSPACE / ".lae" / "parameter_updates.jsonl",
                          encoding="utf-8", errors="replace"):
            try:
                _r = json.loads(_line)
            except Exception:
                continue
            _src = str(_r.get("source") or "")
            if not _src.startswith("l5g-"):
                continue
            try:
                _ts = time.mktime(time.strptime(str(_r.get("ts")), "%Y-%m-%d %H:%M:%S"))
                _val = float(_r.get("new_value"))
            except Exception:
                continue
            if _ts + L5_PARAM_HOLD_S > now:
                _L5_PARAM_HOLD[str(_r.get("key"))] = [_ts + L5_PARAM_HOLD_S, _val, _src]
    except Exception as _e:
        print(f"[param-hold] seed error: {_e}", flush=True)


def _l5_hold_block(param_key, param_value, source):
    """None = 允许写; 否则返回拒绝原因。"""
    _l5_hold_seed()
    ent = _L5_PARAM_HOLD.get(param_key)
    if not ent or time.time() >= ent[0]:
        return None
    try:
        if float(param_value) == float(ent[1]):
            return None          # 写同值不算抢占
    except Exception:
        pass
    src = str(source or "")
    if src.startswith(("l5g-", "operator", "user", "hermes", "ttl", "boot")):
        return None      # boot_replay 是落盘恢复, 被挡会让键回到未设置态
    return (f"L5 landing {ent[2]} = {ent[1]} holds until "
            f"{time.strftime('%H:%M:%S', time.localtime(ent[0]))}; "
            f"'{src}' cannot overwrite inside the readback window "
            f"(EGO_L5_PARAM_HOLD_S=0 disables)")


# ─── 2026-11-12: 已验证结论 / 进行中试验的写保护 ──────────────────────────────
# Only an explicit operator/human write may override. Everything the ego does
# to itself (L5 goals, L10 regulation, evolution, retained candidates) has to
# earn the change through a randomized trial instead. That is the L2 loop.
_OPERATOR_PARAM_SOURCES = ("operator", "user", "hermes", "ttl")


def _trial_guard_block(param_key, param_value, source):
    """None = allow the write; otherwise a refusal reason.

    Two distinct things are protected, both measured on 2026-11-12:

    1. Internal validity of a LIVE trial. L5 goal l5g-20261112-071767 wrote
       integrator_concentration_floor 0.3 -> 0.1 at 18:28:16 (tick 71778)
       WHILE cab_type_dominance_cap_1794478304 was collecting matched pairs.
       The first 8 pairs were a clean +0.05 (control ~0.74, intervention
       ~0.79); after the write the last 3 pairs collapsed to 0.53-0.62 in
       BOTH arms and the paired CI went from excluding zero to
       [-0.0213, +0.0626]. A foreign write halfway through a measurement is
       not noise, it is a different experiment. `SelfExperimenter._apply`
       writes its arms via _apply_evolved_params(), which never enters this
       channel, so arming does not interfere with the trial's own A/B.
    2. Durability of a VERIFIED conclusion. That same L5 write overwrote the
       RCT-verified floor 0.3 with a value its own result.json called
       "behavioral effect pending and honestly unproven". Because
       _apply_runtime_param writes BOTH `current` and runtime_params.json, the
       boot guard's `current == snapshot` check mistook it for a deliberate
       operator edit and would have kept 0.1 forever. Learn once, erase once.

    An operator override is still possible with an explicit source; it is
    recorded by _record_verified_override so the provenance chain says who
    overturned the evidence and why.
    """
    src = str(source or "")
    if src.startswith("boot"):
        return None                 # restoring provenance, not a new decision
    explicit = src.startswith(_OPERATOR_PARAM_SOURCES)
    if (RESTING_STATE.get("self_experiment_armed") and not explicit
            and param_key in PARAM_WHITELIST):
        return ("randomized trial in flight: a foreign write would change the "
                "machine being measured (use an operator source to force)")
    verified = _replay_verified_value(param_key)
    if verified is not None and not explicit:
        try:
            differs = abs(float(param_value) - verified) > 1e-9
        except (TypeError, ValueError):
            differs = True
        if differs:
            return (f"RCT-verified value {verified} is protected; an "
                    "unmeasured edit must be tested, not applied")
    return None


def _record_verified_override(param_key, verified, new_value, source, reason):
    """An explicit operator overturns a trial result: leave a written reason."""
    try:
        ent = (SELF_MODEL_EVOLUTION.get("parameters") or {}).get(param_key)
        if not isinstance(ent, dict):
            return False
        ent.setdefault("history", []).append({
            "tick": int(RESTING_STATE.get("tick", 0) or 0),
            "old": float(verified),
            "new": float(new_value),
            "reason": f"operator override of verified value ({source})",
            "detail": str(reason)[:200],
            "source": source,
            "ts": time.strftime("%Y-%m-%d %H:%M:%S"),
        })
        # history[-1] is no longer a verified intervention, so
        # _replay_verified_value returns None from here on and boot replay
        # stops protecting this parameter - but the reason is on disk.
        _persist_self_model_evolution(
            f"operator override of RCT-verified {param_key} at tick "
            f"{RESTING_STATE.get('tick', 0)}")
        print(f"[param-guard] recorded operator override {param_key} "
              f"{verified}->{new_value}; trial-verified protection released",
              flush=True)
        # 2026-11-13 conflict-as-trial: an override that runs against pooled
        # confirmed evidence is not wrong (the operator may know something),
        # but the disagreement must be MEASURED, not re-fought. Hand it to the
        # scheduler: control = override value now live, intervention = the
        # verified value. climb rolls the override back; anything else and it
        # stands. Observed overnight: L5 pushed floor 0.35->0.1 through this
        # channel three times while evolve pulled it back three times.
        try:
            if _SELF_EXPERIMENT is not None:
                _SELF_EXPERIMENT.request_conflict_trial(
                    param_key, verified, new_value, reason)
        except Exception as _cte:
            print(f"[param-guard] conflict-trial request failed: {_cte}",
                  flush=True)
        return True
    except Exception as exc:
        print(f"[param-guard] override record failed: {exc}", flush=True)
        return False


# ─── 2026-11-03: 参数过期回滚 ──────────────────────────────────────────────
# 事故模式: 探针(通常来自 L5/L10 自主演化)把旋钮一改就走, 没人回滚。
# 实证: `COACTIVATION_THRESHOLD` 10-29 被 probe 从 2 改成 1, 三周无人回滚, 期间
# 68,990 条共激活对被静默丢弃 (edges_grown 只有 870); `kwta_pool_mult` 10→2 同理。
# 所以 /apply-parameter 支持 ttl_seconds: 到期由 tick 自动写回旧值并留在审计里。
_PARAM_TTL = {}   # key -> {"until": epoch_ts, "restore": old_value, "reason": str}


def _param_ttl_path():
    return WORKSPACE / ".lae" / "param_ttl.json"


def _param_ttl_save():
    try:
        _p = _param_ttl_path()
        _p.parent.mkdir(parents=True, exist_ok=True)
        _p.write_text(json.dumps(_PARAM_TTL, ensure_ascii=False), encoding="utf-8")
    except Exception as _e:
        print(f"[param-ttl] save error: {_e}", flush=True)


def _param_ttl_load():
    try:
        _p = _param_ttl_path()
        if _p.exists():
            _PARAM_TTL.update(json.loads(_p.read_text(encoding="utf-8")) or {})
    except Exception as _e:
        print(f"[param-ttl] load error: {_e}", flush=True)


def _param_ttl_reap(now_ts=None):
    """到期参数写回旧值; 返回本次回滚的键。空表零成本, 幂等。"""
    if not _PARAM_TTL:
        return []
    now_ts = now_ts or time.time()
    done = []
    for _k, _e in list(_PARAM_TTL.items()):
        try:
            if float(_e.get("until", 0) or 0) > now_ts:
                continue
            _old = _e.get("restore")
            if _old == "unset":
                RESTING_STATE.pop(_k, None)
            else:
                _apply_runtime_param(_k, _old,
                                     reason=f"ttl expiry ({_e.get('reason', '')})",
                                     source="ttl_reap")
            _PARAM_TTL.pop(_k, None)
            done.append(_k)
            print(f"[param-expire] {_k} -> {_old} "
                  f"(ttl 到期回滚; 原改动: {_e.get('reason', '')})", flush=True)
        except Exception as _ex:
            print(f"[param-ttl] reap {_k} error: {_ex}", flush=True)
    if done:
        _param_ttl_save()
    return done


_param_ttl_load()


def _param_floor(param_key: str):
    """EGO_PARAM_FLOORS="k=10,k2=2" -> key 的下限; 未配置返回 None (不干预)。"""
    try:
        for _kv in (os.environ.get("EGO_PARAM_FLOORS") or "").split(","):
            _k, _sep, _v = _kv.partition("=")
            if _sep and _k.strip() == param_key:
                return float(_v)
    except Exception:
        return None
    return None


def _edge_cache_stats() -> dict:
    """真实边缓存水位。生产热路径是 EDGE_ACTIVE (tl_ego_server 内),
    不是 neural_grid.EdgeStore(那条只在 EDGE_STORE_V2 缺位时才走)。"""
    out = {}
    try:
        out["active_sources"] = len(EDGE_ACTIVE)
        out["active_edges"] = (_EDGE_ACTIVE_TOTAL if _EDGE_ACTIVE_TOTAL is not None
                               else sum(len(v) for v in EDGE_ACTIVE.values()))
        out["max_sources"] = _EDGE_ACTIVE_MAX_SOURCES
        out["max_edges"] = _EDGE_ACTIVE_MAX_TOTAL_EDGES
        out["est_mb"] = round(out["active_edges"] * 120 / 2 ** 20, 1)
    except Exception as _e:
        out["active_error"] = f"{type(_e).__name__}: {_e}"
    try:
        import neural_grid.neural_grid as _ngi
        _es = getattr(_ngi, "_edge_store", None)
        if _es is not None:
            out["legacy_nodes"] = len(_es._cache)
            out["legacy_edges"] = getattr(_es, "_cache_entries", None)
    except Exception:
        pass
    return out


def _apply_runtime_param(param_key: str, param_value, reason: str = "",
                         source: str = "retained_candidate",
                         ttl_seconds: float = 0.0) -> dict:
    """Whitelist + range check + apply + audit. Returns result dict (never raises)."""
    global A_PLUS, A_MINUS, _TYPE_BUDGET_KWTA_SINGLETON, _TYPE_BUDGET_KWTA_SINGLETON
    try:
        if param_key not in PARAM_WHITELIST:
            return {"ok": False, "reason": f"parameter '{param_key}' not in whitelist"}
        param_value = float(param_value)
        lo, hi = PARAM_RANGES.get(param_key, (0.0, 1e9))
        if not (lo <= param_value <= hi):
            return {"ok": False, "reason": f"value {param_value} out of range [{lo}, {hi}] for {param_key}"}
        # 2026-11-07: L5 落地持有窗口内拒绝被别的演化层覆盖 (见 L5_PARAM_HOLD_S)。
        _blk = _l5_hold_block(param_key, param_value, source)
        if _blk:
            print(f"[param-hold] {param_key}={param_value} from '{source}' blocked: {_blk[:100]}", flush=True)
            return {"ok": False, "reason": f"held by L5 landing — {_blk}"}
        # 2026-11-03: 参数通道有 TTL(防 operator 忘了改回)但没有下限(防被覆盖)。
        # 实测 ego 自主调参 `[param-apply] kwta_pool_mult: 10.0 -> 3.0 (reason=L10
        # kwta_threshold_expansion)` 直接把扩池成果清零 (n_act 1800 -> 540)。
        # 这里给关键旋钮钉下限: EGO_PARAM_FLOORS="kwta_pool_mult=10,xxx=2"。
        # 只在 operator 显式设置时生效, 默认不干预自主调参。
        _floor = _param_floor(param_key)
        if _floor is not None and param_value < _floor:
            print(f"[param-floor] {param_key}: {param_value} < floor {_floor} -> {_floor} "
                  f"(被拒的下调 reason={reason[:50]})", flush=True)
            param_value = _floor
        # 2026-11-12: refuse an unmeasured edit that would either change the
        # machine a live RCT is measuring, or overturn a value that RCT has
        # already verified. Both were observed destroying a real climb.
        _verified_before = _replay_verified_value(param_key)
        _gblk = _trial_guard_block(param_key, param_value, source)
        if _gblk:
            print(f"[param-guard] {param_key}={param_value} from '{source}' "
                  f"blocked: {_gblk}", flush=True)
            return {"ok": False, "reason": _gblk}
        old_value = RESTING_STATE.get(param_key, None)
        if old_value is None:
            if param_key == "jepa_calibration_factor":
                old_factor, _, _ = _load_jepa_calibration()
                old_value = old_factor
            elif param_key == "stdp_learning_rate":
                old_value = A_PLUS
            elif param_key == "coactivation_threshold":
                # 2026-11-03: 旧值必须取模块常量本身, 否则 TTL 回滚会拿到 "unset",
                # 只清 RESTING_STATE 而模块常量仍是改后的值 = 回滚无效。
                try:
                    import edge_sparsifier as _es0
                    old_value = int(_es0.COACTIVATION_THRESHOLD)
                except Exception:
                    old_value = "unset"
            else:
                old_value = "unset"
        if param_key == "jepa_calibration_factor":
            _, ema_alpha, cal_history = _load_jepa_calibration()
            _hold_tick = (RESTING_STATE.get("tick", 0) or 0) + 20
            _save_jepa_calibration(param_value, ema_alpha, cal_history, hold_until_tick=_hold_tick)
        elif param_key == "coactivation_threshold":
            # 2026-11-03: 真消费者 = edge_sparsifier 模块常量 (每次 coactivation_update
            # 都读它)。只写 RESTING_STATE 没有消费者 = 死写, 所以两边都写。
            import edge_sparsifier as _es
            _es.COACTIVATION_THRESHOLD = int(param_value)
            RESTING_STATE[param_key] = int(param_value)
        elif param_key == "stdp_learning_rate":
            # 2026-09-18 wiring fix: 处方此前零消费者(RESTING_STATE 键无人读)。
            # 真实 STDP 速率 = A_PLUS/A_MINUS(LTD 同步缩放, 保 5% 反对称比)。
            ratio = A_MINUS / A_PLUS if A_PLUS else 1.05
            A_PLUS = float(param_value)
            A_MINUS = float(param_value) * ratio
        else:
            RESTING_STATE[param_key] = param_value
        # l5g-20261031-062241: the live consumer of type_budget_kwta_budget is
        # _TYPE_BUDGET_KWTA_SINGLETON, which caches type_budget at construction
        # (call sites 4359-4361 / 11137-11139 build it only when None). Without
        # invalidation a runtime write only updates RESTING_STATE/audit/snapshot
        # while the gate keeps the old budget - measured: after write 64->32 the
        # log printed budget=32.0 but output_sum stayed 1152 (=64*18 types).
        if param_key == "type_budget_kwta_budget":
            _TYPE_BUDGET_KWTA_SINGLETON = None
        # 2026-11-12: the self-model must agree with what is actually running.
        # Boot replay and operator writes land here and nowhere else, so without
        # this the scheduler kept proposing trials against a baseline the live
        # generation had already left behind (measured: evidence_persist_ticks
        # replayed to 20.0 on twelve restarts while `current` still said 10.0).
        _mirror_param_to_self_model(param_key, param_value, source=source)
        if (_verified_before is not None
                and abs(float(param_value) - _verified_before) > 1e-9
                and str(source or "").startswith(_OPERATOR_PARAM_SOURCES)):
            _record_verified_override(param_key, _verified_before, param_value,
                                      source, reason)
        audit_path = WORKSPACE / ".lae" / "parameter_updates.jsonl"
        try:
            audit_path.parent.mkdir(parents=True, exist_ok=True)
            with open(audit_path, "a", encoding="utf-8") as af:
                af.write(json.dumps({
                    "ts": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "tick": RESTING_STATE.get("tick", 0),
                    "key": param_key,
                    "old_value": old_value,
                    "new_value": param_value,
                    "reason": reason,
                    "source": source,
                }, ensure_ascii=False) + "\n")
        except Exception:
            pass
        # 2026-11-03: TTL 登记(只在成功写入后)。到期 _param_ttl_reap 写回 old_value,
        # 这样"改了就走的探针"不会再留下永久副作用。
        if ttl_seconds and float(ttl_seconds) > 0:
            _PARAM_TTL[param_key] = {
                "until": time.time() + float(ttl_seconds),
                "restore": old_value,
                "reason": reason,
            }
            _param_ttl_save()
            print(f"[param-ttl] {param_key}={param_value} 将在 "
                  f"{int(float(ttl_seconds))}s 后回滚到 {old_value}", flush=True)
        # 2026-09-18 persistence fix: 处方此前只写内存, 重启即失忆
        # (实测: 09-16 处方 stdp_learning_rate=0.04, 09-18 重启后 old_value 回 "unset")。
        # 全量处方快照落盘, 启动时在 _load_runtime_params 重放。
        try:
            if param_key == "jepa_calibration_factor":
                _cur, _, _ = _load_jepa_calibration()
            elif param_key == "stdp_learning_rate":
                _cur = A_PLUS
            else:
                _cur = RESTING_STATE.get(param_key, param_value)
            _snap_path = WORKSPACE / ".lae" / "runtime_params.json"
            _snap = {}
            if _snap_path.exists():
                try:
                    _snap = json.loads(_snap_path.read_text(encoding="utf-8"))
                except Exception as _snap_err:
                    # l5g-20261031-062373: a corrupt snapshot must not silently
                    # reset the file to one key - preserve it and fail loud.
                    print(f"[param-snap] corrupt runtime_params.json preserved: {_snap_err}", flush=True)
                    try:
                        _snap_path.replace(_snap_path.with_name(_snap_path.name + ".corrupt"))
                    except Exception:
                        pass
                    # l5g-20261105-065711: the except above fires on ANY read
                    # failure incl. transient Windows file locks; the preserved
                    # .corrupt bytes are usually valid JSON (measured 2026-11-04
                    # 17:11:47: 8 prescriptions collapsed to 1 key; floor/cap/
                    # stagnation_threshold/stdp/drive_decay/evidence/coactivation
                    # silently reverted to defaults). Salvage intact pairs from
                    # the preserved text instead of dropping sibling keys.
                    try:
                        _salv = _snap_path.with_name(
                            _snap_path.name + ".corrupt").read_text(encoding="utf-8", errors="replace")
                        for _m in re.finditer(r'"([A-Za-z0-9_]+)"\s*:\s*(-?[0-9]+(?:\.[0-9]+)?|"[^"]*")', _salv):
                            if _m.group(1) in PARAM_WHITELIST:
                                try:
                                    _snap[_m.group(1)] = json.loads(_m.group(2))
                                except Exception:
                                    pass
                        if _snap:
                            print(f"[param-snap] salvaged {len(_snap)} keys from preserved snapshot", flush=True)
                    except Exception:
                        _snap = {}
            _snap[param_key] = _cur
            # l5g-20261031-062373: atomic write (tmp + os.replace) so a kill
            # mid-write cannot leave a truncated snapshot that the next boot
            # fails to parse (measured: 12 keys -> 1 key across the 04:46 boot).
            _snap_tmp = _snap_path.with_name(_snap_path.name + ".tmp")
            _snap_tmp.write_text(json.dumps(_snap, ensure_ascii=False, indent=1), encoding="utf-8")
            os.replace(_snap_tmp, _snap_path)
        except Exception:
            pass
        print(f"[param-apply] {param_key}: {old_value} -> {param_value} (reason={reason[:60]})", flush=True)
        # 2026-11-07: L5 落地即接管该键写权; 非 L5 写入只要值真的变了就释放旧持有,
        # 免得一个过期持有长期挡住后续正常调参。
        _src0 = str(source or "")
        if _src0.startswith("l5g-"):
            _L5_PARAM_HOLD[param_key] = [time.time() + L5_PARAM_HOLD_S, param_value, _src0]
        elif not _src0.startswith("boot"):
            _ent0 = _L5_PARAM_HOLD.get(param_key)
            try:
                _same0 = _ent0 is not None and float(param_value) == float(_ent0[1])
            except Exception:
                _same0 = False
            if not _same0:
                _L5_PARAM_HOLD.pop(param_key, None)
        return {"ok": True, "key": param_key, "old_value": old_value, "new_value": param_value}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def _snapshot_runtime_param(key: str, value: float) -> None:
    """Record an adopted value in runtime_params.json without touching history.

    The gate applies through _apply_evolved_params(), which never reaches
    _apply_runtime_param, so the snapshot kept the pre-trial value forever and
    boot replay restored it every generation (see
    _replay_should_defer_to_self_model for the measured 11-in-one-day rollback).
    Keeping the two sources in sync is the root fix; the boot guard is the
    belt-and-braces on top of it.

    Same atomic write as _apply_runtime_param: a kill mid-write must not leave a
    truncated snapshot the next boot cannot parse.
    """
    try:
        path = WORKSPACE / ".lae" / "runtime_params.json"
        snap = {}
        if path.exists():
            try:
                snap = json.loads(path.read_text(encoding="utf-8"))
            except Exception:
                snap = {}
        if not isinstance(snap, dict):
            snap = {}
        snap[key] = value
        tmp = path.with_name(path.name + ".tmp")
        tmp.write_text(json.dumps(snap, ensure_ascii=False, indent=1), encoding="utf-8")
        os.replace(tmp, path)
    except Exception as exc:
        print(f"[param-snap] sync failed for {key}: {exc}", flush=True)


def _mirror_param_to_self_model(param_key: str, value, source: str = "runtime_apply") -> bool:
    """One knob must not have two values.

    Measured 2026-11-12: boot replay set evidence_persist_ticks 10 -> 20.0 on
    twelve consecutive restarts, but the self-model's `current` stayed at 10.0
    because _apply_runtime_param only wrote RESTING_STATE. The scheduler reads
    `current` to choose a trial's control arm, so every trial of that lever ran
    10-vs-X on a machine already at 20 — the reading described a lever the
    system was not using. Worse, a finished trial restores its control arm, so
    the generation dropped to 10 and the next boot put it back to 20: the
    parameter's value depended on whether the process had restarted since.

    Only `current` is mirrored. `history` stays the record of how the value was
    decided — that is what the gate reads and what the boot-replay guard checks.
    """
    try:
        ent = (SELF_MODEL_EVOLUTION.get("parameters") or {}).get(param_key)
        if not isinstance(ent, dict):
            return False
        ent["current"] = float(value)
        ent["last_source"] = source
        ent["last_applied_tick"] = int(RESTING_STATE.get("tick", 0) or 0)
        return True
    except Exception:
        return False


def _replay_verified_value(key: str):
    """The value the last randomized trial ACTUALLY adopted, or None.

    `current` is not provenance. Measured 2026-11-12 17:51: a trial of
    integrator_concentration_floor was killed with its intervention arm 0.425
    live in SELF_MODEL_EVOLUTION / RESTING_STATE; the periodic self-model save
    wrote that transient arm to lae_self_model.json as `current`. The old boot
    guard checked only history[-1]["reason"], then skipped replay entirely, so
    boot kept 0.425, discarded the correct snapshot 0.3, and printed "kept
    trial-verified values" about a value that had never been verified. The
    scheduler then opened cab_integrator_concentration_floor_1794477270 with
    control=0.425 / intervention=0.3 - a whole RCT spent rediscovering a number
    it had already verified at tick 70920.

    The durable record is history[-1]["new"], written at the moment of adoption
    together with the reason (_persist_self_model_evolution). Boot must restore
    THAT number, not whatever `current` happens to say after an interrupted
    experiment.
    """
    try:
        pdata = (SELF_MODEL_EVOLUTION.get("parameters") or {}).get(key)
        if not isinstance(pdata, dict):
            return None
        hist = pdata.get("history") or []
        if not hist:
            return None
        last = hist[-1] or {}
        if "verified randomized intervention" not in str(last.get("reason") or ""):
            return None
        val = last.get("new")
        if isinstance(val, bool) or not isinstance(val, (int, float)):
            return None
        return float(val)
    except Exception:
        return None


def _replay_override_value(key: str):
    """The newest DELIBERATE write to a parameter, or None.

    Companion to _replay_verified_value. That function returns None both when
    no trial ever ran AND when a newer operator/l5g override superseded it; the
    two cases are indistinguishable to its caller. So the snapshot replay
    below treated a superseded override as absent provenance and clobbered it:
    the escape hatch stopped the verified-value RESTORE but not the snapshot
    CLOBBER. Measured 2026-11-13 (l5g-20261113-072052): the floor was lowered
    0.35->0.1 on measured evidence at ticks 71605, 71778 and 72027, and
    boot_replay_verified restored 0.35 at every restart since --
    runtime_params.json holds 0.35 while lae_self_model.json holds current=0.1
    with the override entry on disk, i.e. the two provenance stores disagree
    right now.

    history[-1] is the write-through record. If its reason is NOT a verified
    randomized intervention, its "new" is the newest deliberate value and the
    snapshot (which never learns about self-model-path writes) is stale. Heal
    the snapshot to it instead of applying the stale number.
    """
    try:
        pdata = (SELF_MODEL_EVOLUTION.get("parameters") or {}).get(key)
        if not isinstance(pdata, dict):
            return None
        hist = pdata.get("history") or []
        if not hist:
            return None
        last = hist[-1] or {}
        if "verified randomized intervention" in str(last.get("reason") or ""):
            return None
        val = last.get("new")
        if isinstance(val, bool) or not isinstance(val, (int, float)):
            return None
        return float(val)
    except Exception:
        return None


def _replay_should_defer_to_self_model(key: str) -> bool:
    """A randomized trial outranks a cache of unknown provenance.

    2026-11-12 measured the damage: `integrator_concentration_floor` was pushed
    from 0.12 to 0.30 at tick 70920 by a preregistered 10-vs-10 randomized
    controlled trial — the only causal discovery this system has ever made — and
    the boot replay then forced it back on *every* restart. Eleven times in one
    day, `old_value=0.3` in parameter_updates.jsonl:

        07:30 0.3->0.12   08:40 0.3->0.12   08:40 0.3->0.12   08:52 0.3->0.12
        08:53 0.3->0.12   09:02 0.3->0.12   09:03 0.3->0.12   09:30 0.3->0.12
        10:21 0.3->0.12                    11:33 0.3->0.06   12:07 0.3->0.06

    Root cause: the gate adopts through _apply_evolved_params(), which never
    touches runtime_params.json; _apply_runtime_param only snapshots values it
    was itself asked to write. So the snapshot never learns about an adoption,
    and at boot it is treated as authoritative over the self-model that does
    record it. Learn once, erase once — accumulation is impossible, which is the
    entire point of the L2 loop.

    Rule: if the self-model's most recent record for a parameter is a verified
    intervention, boot replay does not get to overwrite it. Nothing is locked
    forever — any later change (operator, l5g mutation, evolution) appends its
    own entry without that reason, and this stops applying.
    """
    return _replay_verified_value(key) is not None


def _load_runtime_params() -> None:
    """2026-09-18: boot 时重放 runtime_params.json, 处方跨重启存活。
    在 _load_self_model_narrative() 之后调用(prescription 优先于 checkpoint 旧值)。

    2026-11-12: 但"处方"不能压过"试验结论" —— 见
    _replay_should_defer_to_self_model / _replay_verified_value。
    18:02 起也不再是"跳过回放"，而是显式恢复 history[-1]["new"]：
    被 kill 的试验会把干预臂留在 self-model `current` 里，跳过等于把
    从未验证过的值当成已验证值保留下来。
    """
    try:
        p = WORKSPACE / ".lae" / "runtime_params.json"
        if not p.exists():
            return
        snap = json.loads(p.read_text(encoding="utf-8"))
        n = 0
        kept = []
        for k, v in snap.items():
            if k not in PARAM_WHITELIST:
                continue
            verified = _replay_verified_value(k)
            if verified is not None:
                # No "current == snapshot means deliberate" escape hatch.
                # Measured 18:28: L5 goal l5g-20261112-071767 wrote BOTH the
                # self-model `current` AND this snapshot to 0.1, so the old
                # check classified an unmeasured heuristic edit as a legitimate
                # operator override and would have erased the RCT-verified 0.3
                # permanently. A genuine override appends an override history
                # entry (_record_verified_override), which makes
                # _replay_verified_value return None in the first place.
                #
                # Do not merely "keep current": RESTORE the provenance value
                # through the normal write path so RESTING_STATE, self-model
                # and snapshot all agree, and the stale snapshot is healed
                # permanently instead of re-fought on every boot.
                res = _apply_runtime_param(
                    k, verified,
                    reason="boot replay: restore last verified randomized intervention",
                    source="boot_replay_verified")
                if res.get("ok"):
                    kept.append(f"{k}={v}->{verified} (restored from verified history)")
                else:
                    kept.append(f"{k}={v}->{verified} (BLOCKED: {res.get('reason')})")
                continue
            # l5g-20261113-072052: the override escape hatch was
            # half-implemented. _replay_verified_value(k) is None releases the
            # trial-verified protection, but the snapshot replay below then
            # overwrote the override anyway -- so every measured floor repair
            # was reverted at the next boot. history[-1] without the verified
            # reason IS the newest deliberate write; honour it and heal the
            # snapshot rather than clobbering it.
            override = _replay_override_value(k)
            if override is not None:
                res = _apply_runtime_param(
                    k, override,
                    reason="boot replay: honour newer self-model override, heal stale snapshot",
                    source="boot_replay_override")
                if res.get("ok"):
                    kept.append(f"{k}={v}->{override} (override newer than snapshot)")
                else:
                    kept.append(f"{k}={v}->{override} (BLOCKED: {res.get('reason')})")
                continue
            _res = _apply_runtime_param(k, v, reason="boot replay from runtime_params.json", source="boot_replay")
            if _res.get("ok"):
                n += 1
        if n:
            print(f"[param-replay] {n}/{len(snap)} runtime params restored at boot", flush=True)
        if kept:
            # Loud on purpose: silently keeping a value the snapshot disagrees
            # with is exactly the kind of quiet divergence that cost a day.
            print(f"[param-replay] kept trial-verified values over stale snapshot: "
                  f"{', '.join(kept)}", flush=True)
    except Exception as e:
        print(f"[param-replay] error: {e}", flush=True)


def _advance_candidate_lifecycle():
    """Stage 5.5 closed loop part 2: drive proposed/admitted candidates forward.
    - proposed older than ADMIT_AGE_S -> admitted (enters evaluation pool)
    - admitted whose hint target improved -> testing
    - proposed/admitted with no progress after EXPIRE_AGE_S -> expired
    This stops the 'proposed graveyard' (16 candidates stuck forever) by
    giving every hint-candidate a real lifecycle outcome.
    Returns summary dict for logging.
    """
    try:
        from candidate_registry import CandidateRegistry, CandidateRegistryError
        reg = CandidateRegistry(WORKSPACE / ".lae" / "candidate_registry.sqlite")
        now = time.time()
        ADMIT_AGE_S = 60.0
        EXPIRE_AGE_S = 1800.0  # 30 min without progress
        TEST_AGE_S = 600.0  # 10 min verification window (2026-08-15)
        summary = {"admitted": 0, "testing": 0, "expired": 0, "retained": 0, "rejected": 0, "errors": 0}

        # Current state snapshot for improvement check
        stag_now = RESTING_STATE.get("stagnation_streak", 0) or 0
        dom_now = RESTING_STATE.get("last_dominant", "") or ""
        # 2026-08-15 fix(E): last_concentration 从未被写入 RESTING_STATE（7698 行只写
        # 诊断 dict），真实浓度在 resting_concentration。修复前 conc_now 恒 0.0，
        # 导致 integrator/association 分支的 conc>=0.10 永远不成立。
        conc_now = (RESTING_STATE.get("resting_concentration",
                     RESTING_STATE.get("last_concentration", 0.0)) or 0.0)

        active = reg.list_active()
        for cand in active:
            cid = cand["candidate_id"]
            state = cand["state"]
            age = now - float(cand.get("created_at", now))
            try:
                if state == "proposed":
                    if age > EXPIRE_AGE_S:
                        reg.transition(cid, "expired")
                        summary["expired"] += 1
                        print(f"[cand-lifecycle] {cid[:12]} proposed {age:.0f}s -> expired (no progress)", flush=True)
                    elif age > ADMIT_AGE_S:
                        reg.transition(cid, "admitted")
                        summary["admitted"] += 1
                        print(f"[cand-lifecycle] {cid[:12]} proposed {age:.0f}s -> admitted", flush=True)
                elif state == "admitted":
                    if age > EXPIRE_AGE_S:
                        reg.transition(cid, "expired")
                        summary["expired"] += 1
                        print(f"[cand-lifecycle] {cid[:12]} admitted {age:.0f}s -> expired (no verification)", flush=True)
                    else:
                        # Improvement check: candidate hints often mention stagnation
                        # or integrator escape. If stagnation dropped vs candidate birth
                        # or dominant shifted, treat as verified progress -> testing.
                        # l5g-20260814-candidate-diversity: 收紧判定。
                        # 修复前 stag_now < stag_birth（任何下降）即算 improved，今日
                        # margin 修复后 stagnation 自然回落 + integrator 频繁出现 →
                        # 全部 hint 候选假阳性 retained（32/32 同一机制，0 多样化）。
                        # 现在要求实质下降（>=10 tick）且当前仍健康（<30），integrator
                        # 分支要求 hint 含真实机制关键词，排除泛泛观察。
                        try:
                            birth = json.loads(cand.get("birth_state_json") or "{}")
                        except Exception:
                            birth = {}
                        stag_birth = birth.get("stagnation_streak", stag_now + 1)
                        _hint_text = str(cand.get("proposal_json", "")).lower()
                        _mechanism_kw = ("patch" in _hint_text or "edge" in _hint_text
                                         or "seed" in _hint_text or "guard" in _hint_text
                                         or "route" in _hint_text or "threshold" in _hint_text
                                         or "inject" in _hint_text or "override" in _hint_text)
                        # 2026-08-15 fix(D): 解析 association 候选的 to 字段与算子
                        _prop_json = {}
                        try:
                            _prop_json = json.loads(cand.get("proposal_json") or "{}")
                        except Exception:
                            _prop_json = {}
                        _to_type = str(_prop_json.get("to", ""))
                        _op = str(cand.get("mutation_operator", ""))
                        # 2026-08-15 fix(F): _decode() 把 proposal_json -> proposal、
                        # birth_state_json -> birth_state 改名，但此处一直读旧键名，
                        # 导致 _to_type 恒空、integrator 关键词恒 False、stag_birth
                        # 恒为 stag_now+1 —— 三条 improved 分支全部结构性死亡，
                        # 52/52 候选只能等过期，0 个进入 testing。改用新键名。
                        _prop = cand.get("proposal") or {}
                        if not isinstance(_prop, dict):
                            try:
                                _prop = json.loads(_prop) if isinstance(_prop, str) else {}
                            except Exception:
                                _prop = {}
                        _hint_text = str(_prop).lower()
                        _mechanism_kw = any(k in _hint_text for k in (
                            "patch", "edge", "seed", "guard", "route", "threshold",
                            "inject", "override", "修复", "补丁", "阈值", "注入",
                            "路由", "守卫", "规则", "机制", "边"))
                        _to_type = str(_prop.get("to", ""))
                        _op = str(cand.get("mutation_operator", ""))
                        # 2026-08-15 fix(G): association 后验判定——不再要求"当前
                        # dominant 恰好等于 to 类型"（memory 从未成为 dominant，恒死），
                        # 改为验证候选存活期内目标类型是否在 raw_dominant_history 中
                        # 出现过（计数增长），浓度阈值放宽到 0.05。
                        _raw_birth = birth.get("raw_dominant_history") or {}
                        if not isinstance(_raw_birth, dict):
                            _raw_birth = {}
                        _raw_now = RESTING_STATE.get("raw_dominant_history") or {}
                        if not isinstance(_raw_now, dict):
                            _raw_now = {}
                        _to_birth = int(_raw_birth.get(_to_type, 0) or 0) if _to_type else 0
                        _to_now = int(_raw_now.get(_to_type, 0) or 0) if _to_type else 0
                        # ── 2026-08-18 evolution fix: 判据区分度 ──
                        # 之前: 仅要求 _to_now > _to_birth（绝对计数增长）。原始主导历史
                        #       对所有类型随 tick 同步累积 → 该条件几乎恒真 →
                        #       retained:rejected≈34:1，区分度≈0（子代理 08-18 审计）。
                        # 现在: 份额增长——目标类型在主导历史中的占比必须真实上升
                        #       （≥3 个百分点）且绝对增量 ≥3（排除噪声单次命中），
                        #       否则视为"全类型同步增长的巧合"，不进入 testing。
                        _tot_birth = sum(int(v or 0) for v in _raw_birth.values()) or 1
                        _tot_now = sum(int(v or 0) for v in _raw_now.values()) or 1
                        _share_birth = _to_birth / _tot_birth if _tot_birth else 0.0
                        _share_now = _to_now / _tot_now if _tot_now else 0.0
                        improved = (
                            int(stag_birth) - stag_now >= 10 and stag_now < 30
                        ) or (
                            "integrator" in _hint_text
                            and dom_now == "integrator"
                            and conc_now >= 0.10
                            and _mechanism_kw
                        ) or (
                            # 2026-08-15 fix(D)+fix(F): association/inhibition 候选
                            # 第三条路——目标类型在候选存活期内被系统激活过即视为
                            # 机制验证通过（后验证据，不再依赖瞬时 dominant 巧合）。
                            _to_type
                            and _op != "from_l5_next_impulse_hint"
                            and (_to_now - _to_birth) >= 3
                            and (_share_now - _share_birth) >= 0.03
                            and conc_now >= 0.05
                        )
                        if improved:
                            reg.transition(cid, "testing", posterior_effect={
                                "verified_at": now,
                                "stagnation_before": stag_birth,
                                "stagnation_now": stag_now,
                                "dominant_now": dom_now,
                                "concentration_now": conc_now,
                                "target_type": _to_type,
                                "target_activity_birth": _to_birth,
                                "target_activity_now": _to_now,
                            })
                            summary["testing"] += 1
                            print(f"[cand-lifecycle] {cid[:12]} admitted -> testing (stagnation {stag_birth}->{stag_now}, dom={dom_now})", flush=True)
                elif state == "testing":
                    # 2026-08-15 fix(H): testing 状态此前无任何消费方——transition
                    # 只进不出，候选永久卡死（expire_old 也不清理 testing）。
                    # 新增验证窗口：TEST_AGE_S 后复核 stagnation 未反弹 -> retained，
                    # 反弹 -> rejected。真正形成 proposed->admitted->testing->
                    # retained/rejected 完整闭环。
                    if reg.testing_age_seconds(cand, now=now) >= TEST_AGE_S:
                        _post = cand.get("posterior_effect") or {}
                        if not isinstance(_post, dict):
                            try:
                                _post = json.loads(_post) if isinstance(_post, str) else {}
                            except Exception:
                                _post = {}
                        _stag_verified = float(_post.get("stagnation_now", stag_now) or stag_now)
                        # Re-verify: stagnation must not regress >5 (noise tolerance)
                        # and must stay healthy (<30) across the whole window.
                        still_good = (stag_now <= _stag_verified + 5 and stag_now < 30)
                        if still_good:
                            reg.transition(cid, "retained", posterior_effect={
                                "retained_at": now,
                                "verification": "testing window held",
                                "stagnation_verified": _stag_verified,
                                "stagnation_final": stag_now,
                            })
                            summary["retained"] += 1
                            # ── 2026-09-18 retained→runtime hook ──
                            # A retained candidate whose proposal carries
                            # {"param": {"key","value","reason"}} now reaches the
                            # real write-back channel (whitelist+range+audit).
                            try:
                                _rp = (cand.get("proposal") or {})
                                if isinstance(_rp, str):
                                    _rp = json.loads(_rp)
                                _ps = _rp.get("param") or {}
                                if isinstance(_ps, dict) and _ps.get("key"):
                                    _pa = _apply_runtime_param(_ps["key"], _ps.get("value"),
                                                               reason=str(_ps.get("reason") or _rp.get("hint_text",""))[:200],
                                                               source=f"retained:{cid[:16]}")
                                    print(f"[cand-lifecycle] {cid[:12]} retained param apply: {_pa}", flush=True)
                            except Exception as _pa_e:
                                print(f"[cand-lifecycle] {cid[:12]} param hook error: {_pa_e}", flush=True)
                            print(f"[cand-lifecycle] {cid[:12]} testing -> retained (stag {_stag_verified}->{stag_now})", flush=True)
                        else:
                            reg.transition(cid, "rejected", posterior_effect={
                                "rejected_at": now,
                                "reason": f"stagnation regressed {_stag_verified}->{stag_now}",
                            })
                            summary["rejected"] += 1
                            print(f"[cand-lifecycle] {cid[:12]} testing -> rejected (stag {_stag_verified}->{stag_now})", flush=True)
            except CandidateRegistryError as e:
                summary["errors"] += 1
                print(f"[cand-lifecycle] {cid[:12]} transition error: {e}", flush=True)
            except Exception as e:
                summary["errors"] += 1
                print(f"[cand-lifecycle] {cid[:12]} error: {e}", flush=True)
        return summary
    except Exception as e:
        print(f"[cand-lifecycle] init error: {e}", flush=True)
        return {"error": str(e)}


def _publish_hint_to_candidate_registry(hint_text, goal_name):
    """Stage 5.5 closed loop: publish next_impulse_hint into candidate_registry
    so a sandbox conclusion enters the evolution lifecycle instead of dying in
    result.json (87 analyses, zero applied proposals -> this is the bridge)."""
    try:
        from candidate_registry import CandidateRegistry
        reg = CandidateRegistry(WORKSPACE / ".lae" / "candidate_registry.sqlite")
        # l5g-20260814-candidate-diversity: publish 去重。
        # 修复前每个 L5 hint 无条件入池 → 250/379 候选同属 from_l5_next_impulse_hint
        # 单克隆，32 个 retained 全是同一机制（自然波动被误判为有效）。相同 hint_text
        # 已有活跃候选（proposed/admitted/testing）时跳过，强制候选池保持多样化。
        try:
            _existing = reg.list_active()
        except Exception:
            _existing = []
        for _c in _existing:
            try:
                # 2026-08-18 fix: list_active() 经 _decode 已把 proposal_json 重命名为
                # proposal（解码后的 dict）。此前读旧键 proposal_json 恒 None →
                # json.loads("{}") → hint_text 恒 None → 去重恒失效，同一 candidate_id
                # 被重复 publish 十几次（candidate_registry.py:132 _decode）。
                _pj = _c.get("proposal") or {}
            except Exception:
                _pj = {}
            if str(_pj.get("hint_text", ""))[:200] == str(hint_text)[:200]:
                print(f"[hint-registry] skip duplicate hint (active candidate exists)", flush=True)
                return None
        import hashlib as _hl
        _seed = _hl.sha256(f"{hint_text}{time.time()}".encode()).hexdigest()[:16]
        # ── 2026-09-18: machine-readable param suggestion in hints ──
        # Ego may end a hint with a line "PARAM:key=value" (optionally followed
        # by a reason on the same line after '#'). If present and well-formed,
        # store it structurally so the retained→runtime hook can act on it.
        _psug = {}
        for _line in str(hint_text).splitlines():
            _line = _line.strip()
            if _line.upper().startswith("PARAM:") and "=" in _line:
                try:
                    _kv = _line[6:]
                    _k, _rest = _kv.split("=", 1)
                    _v = _rest.split("#", 1)[0].strip()
                    _psug = {"key": _k.strip(), "value": float(_v),
                             "reason": (_rest.split("#", 1)[1].strip() if "#" in _rest else "")}
                    break
                except (ValueError, IndexError):
                    pass  # malformed PARAM line -> ignore, prose hint still published

        _cand = reg.propose(
            parent_candidate_id=None,
            mutation_operator="from_l5_next_impulse_hint",
            proposal={"hint_text": hint_text[:500], "source_goal": goal_name,
                      **({"param": _psug} if _psug else {})},
            birth_generation="L5",
            random_seed=_seed,
            # 2026-08-15 fix(F): 之前不传 birth_state -> 候选 birth 恒 {} ->
            # stag_birth 默认 stag_now+1 -> stagnation 改善分支恒死。现在快照
            # 当前状态作为验证基线（stagnation/dominant/浓度/类型活跃历史）。
            birth_state={
                "tick": RESTING_STATE.get("tick", 0),
                "dominant": RESTING_STATE.get("last_dominant", ""),
                "stagnation_streak": int(RESTING_STATE.get("stagnation_streak", 0) or 0),
                "concentration": float(RESTING_STATE.get("resting_concentration") or 0.0),
                "raw_dominant_history": dict(RESTING_STATE.get("raw_dominant_history") or {}),
            },
            intended_mechanism="sandbox next_impulse_hint -> candidate lifecycle (closed loop)",
            risk=0.3,
        )
        print(f"[hint-registry] published candidate {_cand.get('candidate_id')} from {goal_name}", flush=True)
        return _cand.get("candidate_id")
    except Exception as e:
        print(f"[hint-registry] publish error: {e}", flush=True)
        return None


def _residual_defect_of(data: dict):
    """(name, resolved) from a sandbox result.json. ("", False) when absent.

    Contract 2026-10-14 (see the executor footer in index.js): executors write
    "residual_defect": {"primary_defect", "status": "open"|"resolved", "evidence"}.
    Legacy shapes (plain string, or a copy under snapshot_state) still parse and
    count as open. Before this, NOTHING populated the field (0/97 results), so the
    repeat gate had only lesson keywords to guess with.
    """
    rd = (data.get("snapshot_state") or {}).get("residual_defect") or data.get("residual_defect")
    if not rd:
        return ("", False)
    if isinstance(rd, dict):
        name = str(rd.get("primary_defect") or rd.get("defect") or "").strip()
        status = str(rd.get("status") or "").strip().lower()
        return (name, status in ("resolved", "fixed", "closed"))
    return (str(rd).strip(), False)


def _count_repeated_diagnoses(limit: int = 10, repeat_threshold: int = 3):
    """Scan recent sandbox result.json files for the same root-cause defect.
    Returns (primary_defect, count) if a defect repeats >= repeat_threshold
    times across the most recent results, else (None, 0).
    Purpose: stop the diagnosis treadmill - same defect diagnosed N times
    must switch from 'analyze again' to 'execute existing fix'."""
    try:
        sandbox_dir = WORKSPACE / "ego_sandbox"
        if not sandbox_dir.exists():
            return (None, 0)
        files = []
        for goal_dir in sandbox_dir.iterdir():
            if not goal_dir.is_dir():
                continue
            rj = goal_dir / "result.json"
            if rj.exists():
                files.append((rj.stat().st_mtime, rj, goal_dir.name))
        files.sort(key=lambda x: x[0], reverse=True)
        defects = []
        for _, rj, gname in files[:limit]:
            try:
                data = json.loads(rj.read_text(encoding="utf-8"))
            except Exception:
                continue
            defect, _resolved = _residual_defect_of(data)
            if _resolved:
                # 2026-10-14: a defect its own result marked resolved must not keep
                # counting as "repeating" — this is what retires finished work.
                continue
            if not defect and data.get("lesson"):
                lesson = data["lesson"].lower()
                # 2026-10-14: only SPECIFIC defect names count here. The generic
                # words "architect"/"suppression" are channel/mechanism names, and
                # measured: 6/6 lessons mentioning "architect" were plain status
                # lines (dominant=architect) -> the gate fired 64x in one window
                # and suppressed 4 analysis goal types for nothing. The structured
                # residual_defect field is never populated, so this list IS the
                # only signal: keep it precise.
                for kw in ("candidate_pool_too_narrow", "escape threshold", "stagnation lock",
                           "curiosity_activation_threshold", "integrator_dom_rate_ceiling"):
                    if kw in lesson:
                        defect = kw
                        break
            if defect:
                defects.append((str(defect), gname))
        if not defects:
            return (None, 0)
        import collections as _collections
        _counter = _collections.Counter(d for d, _ in defects)
        _top_defect, _top_count = _counter.most_common(1)[0]
        if _top_count >= repeat_threshold:
            return (_top_defect, _top_count)
        return (None, 0)
    except Exception:
        return (None, 0)


def _resolved_defects(limit: int = 30) -> dict:
    """{defect_name: evidence} for defects recent results marked resolved.

    Reads the same sandbox results the repeat gate reads; no separate registry
    file, so nothing to persist or go stale. ponytail: last `limit` results by
    mtime — if resolved defects ever need to outlive the sandbox window, promote
    this to a sidecar ledger.
    """
    out = {}
    try:
        sandbox_dir = WORKSPACE / "ego_sandbox"
        if not sandbox_dir.exists():
            return out
        files = []
        for goal_dir in sandbox_dir.iterdir():
            rj = goal_dir / "result.json"
            if goal_dir.is_dir() and rj.exists():
                files.append((rj.stat().st_mtime, rj))
        for _, rj in sorted(files, reverse=True)[:limit]:
            try:
                data = json.loads(rj.read_text(encoding="utf-8"))
            except Exception:
                continue
            name, resolved = _residual_defect_of(data)
            if name and resolved:
                rd = data.get("residual_defect") if isinstance(data.get("residual_defect"), dict) else {}
                out.setdefault(name, str(rd.get("evidence") or data.get("lesson") or "")[:160])
    except Exception:
        pass
    return out


def _resolved_defects_note(limit: int = 4) -> str:
    """Compact 'already fixed — do not redo' block for new L5 goal text."""
    try:
        fixed = _resolved_defects()
        if not fixed:
            return ""
        rows = list(fixed.items())[:limit]
        return ("\n\n[已修复缺陷 — 不要重新诊断或重做, 除非有新测量推翻]\n"
                + "\n".join(f"- {n}: {e}" for n, e in rows))
    except Exception:
        return ""


def _recent_lessons_for_goal(goal_text: str, limit: int = 5) -> str:
    """Lesson reflow (2026-09-16): return a compact block of recent, deduped,
    keyword-relevant lessons from l5_goal_results.jsonl for injection into the
    L5 trigger goal text. Fixes re-learning: RCON-vs-scan lesson was re-derived
    5x in one day because lessons never flowed back into new goals."""
    try:
        path = WORKSPACE / ".lae" / "l5_goal_results.jsonl"
        if not path.exists():
            return ""
        lines = path.read_text(encoding="utf-8", errors="replace").strip().splitlines()[-400:]
        kw = {"scan", "viewer", "rcon", "coordinate", "suppression", "suppress",
              "pool", "retriev", "memorybus", "verify", "torch", "build", "goto"}
        seen_txt, out = set(), []
        for ln in reversed(lines):
            try:
                d = json.loads(ln)
            except Exception:
                continue
            lesson = (d.get("lesson") or d.get("key_finding") or "").strip()
            if not lesson or len(lesson) < 30:
                continue
            key = lesson[:80].lower()
            if key in seen_txt:
                continue
            low = lesson.lower()
            if goal_text and not any(k in low for k in kw) and not any(k in goal_text.lower() for k in kw):
                continue
            seen_txt.add(key)
            out.append(f"- {lesson[:220]}")
            if len(out) >= limit:
                break
        if not out:
            return ""
        return "\n[RECENT LESSONS - do not re-derive, build on these]\n" + "\n".join(out) + "\n"
    except Exception:
        return ""


